-- MARK: Authenticator System
local keyListUrl = "https://amiwamenukeys-default-rtdb.asia-southeast1.firebasedatabase.app/.json"
local KeysBin = MachoWebRequest(keyListUrl)
local CurrentKey = MachoAuthenticationKey()

local function getAuthorizedUser()
    if not KeysBin then return nil end
    local success, keys = pcall(json.decode, KeysBin)
    if not success or not keys or type(keys) ~= "table" then return nil end
    for _, keyData in ipairs(keys) do
        if tostring(keyData.key) == tostring(CurrentKey) then 
            return keyData 
        end
    end
    return nil
end

local AuthorizedData = getAuthorizedUser()
local Key_Authorized = (AuthorizedData ~= nil)
local User_Name = (AuthorizedData and AuthorizedData.user) or "Unknown User"
local Key_Auth = CurrentKey or "INVALID"
local Key_Admin = (AuthorizedData and AuthorizedData.admin) or false
local Key_Expires = (AuthorizedData and AuthorizedData.expires) or "Lifetime"

if not Key_Authorized then
    MachoMenuNotification("error", "Amiwa MENU", "UNAUTHORIZED ACCESS ATTEMPTED!", 5000)
    
    CreateThread(function()
        while true do
            Wait(0)
            
            HideHudAndRadarThisFrame()
            
            DrawRect(0.5, 0.5, 1.0, 1.0, 0, 102, 204, 255)
            
            SetTextFont(4)
            SetTextScale(0.7, 0.7)
            SetTextColour(255, 255, 255, 255)
            SetTextCentre(true)
            SetTextEntry("STRING")
            AddTextComponentString(":( \n\nUNAUTHORIZED ACCESS DETECTED\n\nYour key was not found in the database.\nNICE TRY.")
            DrawText(0.5, 0.4)
        end
    end)
    
    return
end

if Key_Authorized then
    MachoMenuNotification("success", "Amiwa MENU", "Welcome, " .. User_Name .. "! Authorized.", 4000)

    print("Key: " .. User_Name .. " | " .. Key_Auth .. " | Expires: " .. Key_Expires)
