local WaveShieldDetected = GetResourceState("WaveShield") == "started"
local ReaperV4Detected   = GetResourceState("ReaperV4") == "started"

local function acInjectable(name)
    if MachoResourceInjectable and MachoResourceInjectable(name) then return true, name end
    return false, ""
end
local function acScanPaths(paths, minHits)
    for i = 0, GetNumResources() - 1 do
        local r = GetResourceByFindIndex(i)
        if r then
            local hit = 0
            for _, p in ipairs(paths) do if LoadResourceFile(r, p) then hit = hit + 1 end end
            if hit >= minHits then return true, r end
        end
    end
    return false, ""
end
local function acScanAllFiles(files)
    for i = 0, GetNumResources() - 1 do
        local res = GetResourceByFindIndex(i)
        if res then
            local ok = true
            for _, f in ipairs(files) do if not LoadResourceFile(res, f) then ok = false; break end end
            if ok then return true, res end
        end
    end
    return false, ""
end

_G.ShadowDetect_WaveShield = function() return acInjectable("WaveShield") end
_G.ShadowDetect_EagleAC     = function() return acInjectable("EC_AC") end
_G.ShadowDetect_FeloxAC     = function() return acInjectable("FeloxAC") end
_G.ShadowDetect_OTAC        = function() return acInjectable("0T_AC") end
_G.ShadowDetect_GuidAC      = function() return acInjectable("GuidAC") end
_G.ShadowDetect_SniffAC     = function() return acInjectable("SniffAc") end
_G.ShadowDetect_ElectronAC = function() return acScanPaths({ "src/client/main.lua", "src/include/client.lua", "web/index.html", "web/index.js", "fxmanifest.lua" }, 3) end
_G.ShadowDetect_FiveGuard  = function()
    for i = 0, GetNumResources() - 1 do
        local resource = GetResourceByFindIndex(i)
        if resource then
            for j = 0, GetNumResourceMetadata(resource, "client_script") - 1 do
                local meta = GetResourceMetadata(resource, "client_script", j)
                if meta and meta:lower():find("obfuscated") then return true, resource end
            end
        end
    end
    return false, ""
end
_G.ShadowDetect_FiniAC     = function() return acScanAllFiles({ "anticheat.html", "fini_events.js", "fini_events.lua", "client/client.js" }) end
_G.ShadowDetect_Reaper     = function()
    for i = 0, GetNumResources() - 1 do
        local res = GetResourceByFindIndex(i)
        if res then
            local fx = LoadResourceFile(res, "fxmanifest.lua")
            if fx then
                local lower = fx:lower()
                if lower:find("reaperac") or lower:find("https://reaperac%.com/") then return true, res end
            end
        end
    end
    return acInjectable("ReaperV4")
end
_G.ShadowDetect_CyberAC = function() return acScanPaths({ "acmenu/dist/index.html", "client/client-obfuscated.lua", "client/functions-obfuscated.lua", "client/menu-obfuscated.lua", "data/hashes.json" }, 3) end
_G.ShadowDetect_FYAC    = function() return acScanPaths({ "clientpanticheat.lua", "pwucac.lua", "fyac.lua" }, 2) end
_G.ShadowDetect_WardenAC = function()
    local f, r = acInjectable("WardenAC")
    if f then return true, r end
    return acScanPaths({ "dist/include.lua", "dist/client.js", "watch/web/main.js", "watch/web/cfx-three.min.js", "watch/web/index.html" }, 3)
end
_G.ShadowDetect_PhoenixAC = function()
    for _, name in ipairs({ "pac", "pac_iec", "pac_os" }) do
        if MachoResourceInjectable and MachoResourceInjectable(name) then return true, name end
    end
    return acScanPaths({ "pam.obf.lua", "pam.obf.js", "dist/pam.html" }, 2)
end
_G.ShadowDetect_LikizaoAC = function()
    if MachoResourceInjectable and MachoResourceInjectable("likizao_ac") then return true, "likizao_ac" end
    return false, ""
end

local ACDetected = {
    fiveguard = select(1, _G.ShadowDetect_FiveGuard()),
    fyac      = select(1, _G.ShadowDetect_FYAC()),
    warden    = select(1, _G.ShadowDetect_WardenAC()),
    felox     = select(1, _G.ShadowDetect_FeloxAC()),
    otac      = select(1, _G.ShadowDetect_OTAC()),
    fini      = select(1, _G.ShadowDetect_FiniAC()),
    electron  = select(1, _G.ShadowDetect_ElectronAC()),
    eagle     = select(1, _G.ShadowDetect_EagleAC()),
    cyber     = select(1, _G.ShadowDetect_CyberAC()),
    reaper    = ReaperV4Detected or select(1, _G.ShadowDetect_Reaper()),
    guid      = select(1, _G.ShadowDetect_GuidAC()),
    phoenix   = select(1, _G.ShadowDetect_PhoenixAC()),
    likizao   = select(1, _G.ShadowDetect_LikizaoAC()),
}
