function RotToDirection(rotation)
    local radZ = math.rad(rotation.z)
    local radX = math.rad(rotation.x)
    local cosX = math.cos(radX)
    return vector3(-math.sin(radZ) * cosX, math.cos(radZ) * cosX, math.sin(radX))
end

function RotToRight(rotation)
    local radZ = math.rad(rotation.z)
    return vector3(math.cos(radZ), math.sin(radZ), 0)
end

function GetTargetPoint(camCoords, camRot, playerPed)
    local forward = RotToDirection(camRot)
    local target = camCoords + forward * 300.0
    local rayHandle = SafeStartShapeTestRay(camCoords.x, camCoords.y, camCoords.z, target.x, target.y, target.z, -1, playerPed, 0)
    local _, hit, endCoords, _, entityHit = SafeGetShapeTestResult(rayHandle)
    if hit then
        return endCoords, entityHit
    else
        return target, nil
    end
end

function ShowNotification(text)
    BeginTextCommandThefeedPost("STRING")
