    EndTextCommandThefeedPostTicker(true, false)
end

local function GetGameEntitiesInRadius(x, y, z, radius)
    local entities = {}
    local pools = {"CPed", "CVehicle", "CObject", "CPickup"}
    for _, poolType in ipairs(pools) do
        local pool = SafeGetGamePool(poolType)
        for _, entity in ipairs(pool) do
            if SafeDoesEntityExist(entity) then
                local pos = SafeGetEntityCoords(entity)
                if #(pos - vector3(x, y, z)) <= radius then
                    table.insert(entities, entity)
                end
            end
        end
    end
    return entities
end

local function GetClosestVehicleIncludingPlayers(coords, maxDistance)
    local closestVehicle = 0
    local closestDistance = maxDistance
    local handle, vehicle = SafeFindFirstVehicle()
    local success
    
    repeat
        local vehCoords = SafeGetEntityCoords(vehicle)
        local distance = #(coords - vehCoords)
        
        if distance < closestDistance then
            closestDistance = distance
            closestVehicle = vehicle
        end
        
        success, vehicle = SafeFindNextVehicle(handle)
    until not success
    
    SafeEndFindVehicle(handle)
    
    return closestVehicle
end

function DrawMenu()
    if not freeCamActive then return end
    local centerX = 0.5
    local startY = 0.75
    local itemHeight = 0.025
    local textScale = 0.18
    local visibleCount = 8
    
    local startIndex = math.max(1, math.min(selectedOptionIndex - math.floor(visibleCount / 2), #options - visibleCount + 1))
    local endIndex = math.min(startIndex + visibleCount - 1, #options)
    
    for i = startIndex, endIndex do
        local displayIndex = i - startIndex + 1
        local yPos = startY + (displayIndex - 1) * itemHeight
        SafeSetTextFont(0)
        SafeSetTextScale(0.0, textScale)
        if i == selectedOptionIndex then
            SafeSetTextColour(255, 204, 0, 255, 255)
        else
            SafeSetTextColour(150, 150, 150, 255)
        end
        SafeSetTextOutline()
        SafeSetTextCentre(true)
        SafeBeginTextCommandDisplayText("STRING")
        SafeAddTextComponentSubstringPlayerName(options[i].name)
        SafeEndTextCommandDisplayText(centerX, yPos)
    end
    
    local visibleHeight = visibleCount * itemHeight
    local scrollBarX = centerX + 0.022
    local scrollBarY = startY + visibleHeight / 3
    local scrollBarHeight = visibleHeight * 0.4
    local scrollBarWidth = 0.0
    
    local progress = (#options > visibleCount) and ((selectedOptionIndex - 1) / (#options - visibleCount)) or 0
    local indicatorHeight = scrollBarHeight * (visibleCount / #options)
    local indicatorY = scrollBarY - scrollBarHeight / 2 + progress * (scrollBarHeight - indicatorHeight)
    
    SafeDrawRect(scrollBarX, scrollBarY, scrollBarWidth, scrollBarHeight, 40, 40, 40, 120)
    SafeDrawRect(scrollBarX, indicatorY + indicatorHeight / 2, scrollBarWidth, indicatorHeight, 255, 204, 0, 255, 200)
    
    SafeSetTextFont(0)
    SafeSetTextScale(0.0, 0.16)
    SafeSetTextColour(255, 204, 0, 255, 255)
    SafeSetTextOutline()
    SafeSetTextCentre(true)
    SafeBeginTextCommandDisplayText("STRING")
    SafeAddTextComponentSubstringPlayerName(selectedOptionIndex .. "/" .. #options)
    SafeEndTextCommandDisplayText(centerX, startY - 0.025)
    
    SafeSetTextFont(0)
    SafeSetTextScale(0.0, 0.35)
    SafeSetTextColour(255, 204, 0, 255, 220)
    SafeSetTextOutline()
    SafeSetTextCentre(true)
    SafeBeginTextCommandDisplayText("STRING")
    SafeAddTextComponentSubstringPlayerName("+")
    SafeEndTextCommandDisplayText(0.5, 0.49)
    
    local currentAction = options[selectedOptionIndex].action

    if currentAction == "weapon" then
        SafeSetTextFont(0)
        SafeSetTextScale(0.0, 0.18)
        SafeSetTextColour(255, 204, 0, 255, 255)
        SafeSetTextOutline()
