            SafeSetCamFarClip(freeCam, 15000.0)
            SafeOverrideLodscaleThisFrame(2.0)

            if SafeIsControlJustPressed(0, 241) then
                selectedOptionIndex = selectedOptionIndex - 1
                if selectedOptionIndex < 1 then
                    selectedOptionIndex = #options
                end
            elseif SafeIsControlJustPressed(0, 242) then
                selectedOptionIndex = selectedOptionIndex + 1
                if selectedOptionIndex > #options then
                    selectedOptionIndex = 1
                end
            end

            local currentAction = options[selectedOptionIndex].action

            if currentAction == "weapon" and SafeIsControlJustPressed(0, 174) then
                currentWeaponIndex = currentWeaponIndex - 1
                if currentWeaponIndex < 1 then currentWeaponIndex = #weapons end
            elseif currentAction == "weapon" and SafeIsControlJustPressed(0, 175) then
                currentWeaponIndex = currentWeaponIndex + 1
                if currentWeaponIndex > #weapons then currentWeaponIndex = 1 end
            end

            if currentAction == "weapon2" and SafeIsControlJustPressed(0, 174) then
                currentPermKillWeaponIndex = currentPermKillWeaponIndex - 1
                if currentPermKillWeaponIndex < 1 then currentPermKillWeaponIndex = #permKillWeapons end
            elseif currentAction == "weapon2" and SafeIsControlJustPressed(0, 175) then
                currentPermKillWeaponIndex = currentPermKillWeaponIndex + 1
                if currentPermKillWeaponIndex > #permKillWeapons then currentPermKillWeaponIndex = 1 end
            end

            if currentAction == "shoot_animals" and SafeIsControlJustPressed(0, 174) then
