            if currentAction == "shoot_particle" and SafeIsControlJustPressed(0, 174) then
                currentParticleIndex = currentParticleIndex - 1
                if currentParticleIndex < 1 then currentParticleIndex = #particles end
            elseif currentAction == "shoot_particle" and SafeIsControlJustPressed(0, 175) then
                currentParticleIndex = currentParticleIndex + 1
                if currentParticleIndex > #particles then currentParticleIndex = 1 end
            end

            if currentAction == "spawn_object" and SafeIsControlJustPressed(0, 174) then
                currentObjectIndex = currentObjectIndex - 1
                if currentObjectIndex < 1 then currentObjectIndex = #objects end
            elseif currentAction == "spawn_object" and SafeIsControlJustPressed(0, 175) then
                currentObjectIndex = currentObjectIndex + 1
                if currentObjectIndex > #objects then currentObjectIndex = 1 end
            end
        end
    end
end)
    ]])
end)
