    local y = tonumber(MachoMenuGetInputbox(YCoordInput))
    local z = tonumber(MachoMenuGetInputbox(ZCoordInput))
    
    if x and y and z then
        MachoInjectResourceRaw('ox_lib', string.format([[
            local entity
            local playerPed = PlayerPedId()
            if IsPedInAnyVehicle(playerPed, false) and GetPedInVehicleSeat(GetVehiclePedIsIn(playerPed, false), -1) == playerPed then
                entity = GetVehiclePedIsIn(playerPed, false)
