local PlayerSection = MachoMenuGroup(PlayerTab, "Self", 160, 20, 560, 490)
local selectedReviveKey = 0
local function ExecuteRevive()
    local ped = PlayerPedId()
    if DoesEntityExist(ped) then
        MachoInjectResource('esx_ambulancejob', [[
            local ped = PlayerPedId()

            if stopPlayerDeath then
                stopPlayerDeath()
            else
                local coords = GetEntityCoords(ped)
                local heading = GetEntityHeading(ped)

                NetworkResurrectLocalPlayer(coords.x, coords.y, coords.z, heading, false, false)
                SetEntityHealth(ped, GetEntityMaxHealth(ped))
                ClearPedBloodDamage(ped)
                ClearPedTasksImmediately(ped)
                SetPlayerInvincible(ped, false)
                FreezeEntityPosition(ped, false)
                SetCurrentPedWeapon(ped, GetHashKey('WEAPON_UNARMED'), true)

                if StopBleeding then
                    StopBleeding(true)
                end
            end
        ]])

        if Amiwa and Amiwa.Notify then
            Amiwa:Notify("success", "Amiwa", "Revive executed successfully!", 3000)
        end
        MachoMenuNotification("Amiwa", "Revive executed successfully!")
    end
end

MachoMenuKeybind(PlayerSection, "Revive Ryban (Safe)", 0, function(key)
    selectedReviveKey = key
