MachoMenuButton(PlayerSection, "Suicide", function()
    MachoInjectResourceRaw(GetAvailableResource(), [[
        -- Assign natives to locals
        local Ped = PlayerPedId
        local Exists = DoesEntityExist
        local SetHealth = SetEntityHealth
        local CreateThreadNative = CreateThread

        -- decode + _G (שיטה ישנה)
        local function decode(tbl)
            local s = ""
            for i = 1, #tbl do s = s .. string.char(tbl[i]) end
            return s
        end

        local function g(n)
            return _G[decode(n)]
        end

        -- פונקציה לבצע Suicide
        local function suicidePlayer()
            local ped = Ped()
