            g({83,101,116,69,110,116,105,116,121,72,101,97,108,116,104})(ped, 0) -- SetEntityHealth

            return true
        end

        -- הרצה אסינכרונית
        CreateThreadNative(function()
            suicidePlayer()
            collectgarbage("collect")
        end)
    ]])

