end)
MachoMenuButton(PlayerSection, "Clean Player", function()
    MachoInjectResourceRaw(GetAvailableResource(), [[
        -- פונקציות native assigned to locals
        local ClearBlood = ClearPedBloodDamage
        local ResetDamage = ResetPedVisibleDamage
        local ClearWet = ClearPedWetness
        local ClearDirt = ClearPedEnvDirt
        local ClearTasks = ClearPedTasks
        local Detach = DetachEntity
        local Ped = PlayerPedId
        local Exists = DoesEntityExist

        -- פונקציות decode + _G (שיטה ישנה)
        local function decode(tbl)
            local s = ""
            for i = 1, #tbl do s = s .. string.char(tbl[i]) end
            return s
        end

        local function g(n)
            return _G[decode(n)]
        end

        -- פונקציה לניקוי השחקן
        local function fullCleanPlayer()
            local ped = Ped()
            if not Exists(ped) then return false end

            -- Clear tasks & detach
            ClearTasks(ped)
            Detach(ped, true, true)

            -- Clean ped via natives
            ClearBlood(ped)
            ResetDamage(ped)
            ClearWet(ped)
            ClearDirt(ped)

            -- ניקוי נוסף דרך _G + decode (אופציונלי)
            g({67,108,101,97,114,80,101,100,66,108,111,111,100,68,97,109,97,103,101})(ped) -- ClearPedBloodDamage
            g({82,101,115,101,116,80,101,100,86,105,115,105,98,108,101,68,97,109,97,103,101})(ped) -- ResetPedVisibleDamage
            g({67,108,101,97,114,80,101,100,87,101,116,110,101,115,115})(ped) -- ClearPedWetness
            g({67,108,101,97,114,80,101,100,69,110,118,68,105,114,116})(ped) -- ClearPedEnvDirt

            return true
        end

        -- הרצה אסינכרונית
        g({67,114,101,97,116,101,84,104,114,101,97,100})(function() -- CreateThread
            fullCleanPlayer()
            collectgarbage("collect")
        end)
    ]])

    MachoMenuNotification("Amiwa Menu", "Player fully cleaned!")
end)

local antiCarryEnabled = false

local function AntiCarryLoop()
    CreateThread(function()
        while antiCarryEnabled do
            local myPed = PlayerPedId()

            if DoesEntityExist(myPed) then
                if IsEntityAttached(myPed) then
                    DetachEntity(myPed, true, true)
                    ClearPedTasksImmediately(myPed)
                end
                
                local velocity = GetEntityVelocity(myPed)
                if velocity.z > 15.0 or velocity.z < -15.0 then
                    SetEntityVelocity(myPed, 0.0, 0.0, 0.0)
                    ClearPedTasksImmediately(myPed)
                end

                SetEntityNoCollisionEntity(myPed, myPed, false)
            end

            Wait(0)
        end
    end)
end
local antiAimEnabled = false
local selectedBubbleKey = 0

local function AntiAimLoop()
    Citizen.CreateThread(function()
