            ShadowSetPedConfigFlag(ped, 423, true)
        else
            SetPedConfigFlag(ped, 423, true)
        end

        State.godmode = true
        SetEntityInvincible(ped, true)
        SetEntityInvincible(player, true)
        
        if EnableGodmodeHooks then 
            EnableGodmodeHooks() 
        end

        if not _G.__BubbleV2Thread then
            _G.__BubbleV2Thread = true
            CreateThread(function()
                while State.bubblemodeV2 do
                    Wait(0)
                    local p = PlayerPedId()
                    local aggro = IsControlPressed(0, 24) or IsDisabledControlPressed(0, 24) or IsPedShooting(p)
                    NetworkSetFriendlyFireOption(aggro)
                    SetCanAttackFriendly(p, aggro, false)
                    
                    for _, i in ipairs(GetActivePlayers() or {}) do
                        if i ~= PlayerId() then 
                            local targetPed = GetPlayerPed(i)
                            if DoesEntityExist(targetPed) then
                                SetEntityNoCollisionEntity(p, targetPed, true) 
                            end
                        end
                    end
                end
                
                local p = PlayerPedId()
                NetworkSetFriendlyFireOption(true)
                SetCanAttackFriendly(p, true, false)
                
                for _, i in ipairs(GetActivePlayers() or {}) do
                    if i ~= PlayerId() then 
                        local targetPed = GetPlayerPed(i)
                        if DoesEntityExist(targetPed) then
                            SetEntityNoCollisionEntity(p, targetPed, false) 
                        end
                    end
                end
                
                _G.PassiveMode = false
                _G.__BubbleV2Thread = false
