}

-- Corresponding effect data (internal names or settings)
local effectData = {
    { effect = "none" }, -- None option to cancel effects
    { effect = "drunk" },
    { effect = "injured" },
    { effect = "gangster" },
    { effect = "hobo" },
    { effect = "fat" },
    { effect = "nervous" },
    { effect = "weed" },
    { effect = "lsd" },
    { effect = "cocaine" },
    { effect = "heroin" },
    { effect = "adrenaline" },
