    { effect = "nightvision" },
    { effect = "thermal" },
    { effect = "blackout" },
    { effect = "paranoid" },
    { effect = "slowmo" },
    { effect = "speedboost" },
    { effect = "underwater" },
    { effect = "epileptic" }
}

-- Default dropdown choice (1-based index, starting with "None")
local EffectDropDownChoice = 1

-- Initialize Toggles table if it doesn't exist
if not Toggles then
    Toggles = {}
end

-- Create the effect dropdown
local function CreateEffectDropdown()
    EffectDropdown = MachoMenuDropDown(PlayerSection, "Select:", function(Index)
        EffectDropDownChoice = Index + 1 -- Store the selected effect index (1-based)
    end, table.unpack(effectListItems))
end

-- Function to apply or cancel the selected effect using MachoInjectResourceRaw
local function ApplyEffect()
    local effect = effectData[EffectDropDownChoice]
    if effect then
        if effect.effect == "none" then
            -- Cancel all effects
            MachoInjectResourceRaw("any", [[
                SetPedConfigFlag(PlayerPedId(), 100, false)
                SetPedIsDrunk(PlayerPedId(), false)
                ResetPedMovementClipset(PlayerPedId(), 0.0)
                ShakeGameplayCam('DRUNK_SHAKE', 0.0)
                ShakeGameplayCam('VIBRATE_SHAKE', 0.0)
                ShakeGameplayCam('JOLT_SHAKE', 0.0)
                ShakeGameplayCam('ROAD_VIBRATION_SHAKE', 0.0)
                StopAllScreenEffects()
                ClearTimecycleModifier()
                SetNightvision(false)
                SetSeethrough(false)
                SetTimeScale(1.0)
                RestorePlayerStamina(PlayerId(), 100.0)
                Citizen.Wait(100)
            ]])
            Toggles['Effect'] = nil
            MachoMenuNotification("Amiwa Menu", "All effects canceled")
        else
            -- Apply the selected effect
            MachoInjectResourceRaw("any", string.format([[
                -- Clear previous effects first
                SetPedConfigFlag(PlayerPedId(), 100, false)
                SetPedIsDrunk(PlayerPedId(), false)
                ResetPedMovementClipset(PlayerPedId(), 0.0)
                ShakeGameplayCam('DRUNK_SHAKE', 0.0)
                ShakeGameplayCam('VIBRATE_SHAKE', 0.0)
                ShakeGameplayCam('JOLT_SHAKE', 0.0)
                ShakeGameplayCam('ROAD_VIBRATION_SHAKE', 0.0)
                StopAllScreenEffects()
                ClearTimecycleModifier()
                SetNightvision(false)
                SetSeethrough(false)
                SetTimeScale(1.0)
                
                local effectType = "%s"
                
                if effectType == "drunk" then
                    SetPedConfigFlag(PlayerPedId(), 100, true)
                    SetPedIsDrunk(PlayerPedId(), true)
                    ShakeGameplayCam('DRUNK_SHAKE', 1.0)
