                    end
                    SetPedMovementClipset(PlayerPedId(), "move_m@quick", 1.0)
                    SetTimecycleModifier("rply_contrast")
                    
                elseif effectType == "slowmo" then
                    SetTimeScale(0.4)
                    StartScreenEffect("RaceTurbo", 0, true)
                    SetTimecycleModifier("MP_hud_colour_blue")
                    ShakeGameplayCam('ROAD_VIBRATION_SHAKE', 0.1)
                    
                elseif effectType == "speedboost" then
                    SetTimeScale(1.5)
                    StartScreenEffect("MP_Celeb_Win_Out", 0, true)
                    RestorePlayerStamina(PlayerId(), 100.0)
                    SetTimecycleModifier("rply_saturation")
                    
                elseif effectType == "underwater" then
                    StartScreenEffect("MP_OrbitalCannon_Cam", 0, true)
                    SetTimecycleModifier("underwater")
                    RequestAnimSet("move_m@drunk@slightlydrunk")
                    while not HasAnimSetLoaded("move_m@drunk@slightlydrunk") do
                        Citizen.Wait(0)
                    end
                    SetPedMovementClipset(PlayerPedId(), "move_m@drunk@slightlydrunk", 1.0)
                    
                elseif effectType == "epileptic" then
                    StartScreenEffect("MP_TransformRaceFlash", 0, true)
                    StartScreenEffect("HeistTrevorBin", 0, true)
                    ShakeGameplayCam('VIBRATE_SHAKE', 2.0)
                    SetTimecycleModifier("glasses_pink")
                end
                
                Citizen.Wait(100)
            ]], effect.effect))
            Toggles['Effect'] = effect.effect
            MachoMenuNotification("Amiwa Menu", "Applied effect: " .. effectListItems[EffectDropDownChoice])
        end
    else
        MachoMenuNotification("Amiwa Menu", "No effect selected!")
    end
end

-- Function to create a custom drug effect with timer
local function CreateTimedEffect(duration)
    MachoInjectResourceRaw("any", string.format([[
        local effectDuration = %d * 1000 -- Convert to milliseconds
        local startTime = GetGameTimer()
        
        Citizen.CreateThread(function()
            while GetGameTimer() - startTime < effectDuration do
                -- Apply random visual effects during the duration
                local randomEffect = math.random(1, 4)
                if randomEffect == 1 then
                    StartScreenEffect("DrugsMichaelAliensFight", 0, false)
                elseif randomEffect == 2 then
                    StartScreenEffect("DrugsTrevorClownsFight", 0, false)
                elseif randomEffect == 3 then
                    SetTimecycleModifier("spectator" .. math.random(1, 10))
                elseif randomEffect == 4 then
                    ShakeGameplayCam('DRUNK_SHAKE', math.random(1, 3) * 0.5)
                end
                
                Citizen.Wait(math.random(2000, 5000))
            end
            
            -- Clear effects when timer ends
            StopAllScreenEffects()
            ClearTimecycleModifier()
            ShakeGameplayCam('DRUNK_SHAKE', 0.0)
            ShakeGameplayCam('VIBRATE_SHAKE', 0.0)
            ShakeGameplayCam('JOLT_SHAKE', 0.0)
            ShakeGameplayCam('ROAD_VIBRATION_SHAKE', 0.0)
            SetNightvision(false)
            SetSeethrough(false)
            SetTimeScale(1.0)
        end)
    ]], duration or 30))
end

-- Function to apply random drug effect
local function ApplyRandomDrugEffect()
    local drugEffects = {"weed", "lsd", "cocaine", "heroin"}
    local randomDrug = drugEffects[math.random(1, #drugEffects)]
    
    -- Find the index of the random drug effect
    for i, data in ipairs(effectData) do
        if data.effect == randomDrug then
            EffectDropDownChoice = i
            ApplyEffect()
            CreateTimedEffect(math.random(20, 60)) -- Random duration between 20-60 seconds
            break
        end
    end
end

-- Function to completely clear all effects
local function ClearAllEffects()
    MachoInjectResourceRaw("any", [[
        -- Clear all movement effects
        SetPedConfigFlag(PlayerPedId(), 100, false)
        SetPedIsDrunk(PlayerPedId(), false)
        ResetPedMovementClipset(PlayerPedId(), 0.0)
        
        -- Clear all camera effects
        ShakeGameplayCam('DRUNK_SHAKE', 0.0)
        ShakeGameplayCam('VIBRATE_SHAKE', 0.0)
        ShakeGameplayCam('JOLT_SHAKE', 0.0)
        ShakeGameplayCam('ROAD_VIBRATION_SHAKE', 0.0)
        
        -- Clear all screen effects
        StopAllScreenEffects()
        StopScreenEffect("DrugsMichaelAliensFight")
        StopScreenEffect("DrugsTrevorClownsFight")
        StopScreenEffect("DrugsMichaelAliensFightIn")
        StopScreenEffect("DeathFailOut")
        StopScreenEffect("DeathFailNeutralIn")
        StopScreenEffect("DrugsDrivingIn")
        StopScreenEffect("RaceTurbo")
        StopScreenEffect("MP_Celeb_Win")
        StopScreenEffect("MP_Celeb_Lose")
        StopScreenEffect("MP_TransformCheckpointTint")
        StopScreenEffect("MP_TransformRaceFlash")
        StopScreenEffect("MP_OrbitalCannon")
        StopScreenEffect("MP_OrbitalCannon_Cam")
        StopScreenEffect("HeistTrevorBin")
        StopScreenEffect("MP_Celeb_Win_Out")
        StopScreenEffect("MP_Celeb_Lose_Out")
        
        -- Clear all visual modifiers
        ClearTimecycleModifier()
        
        -- Reset vision modes
        SetNightvision(false)
        SetSeethrough(false)
        
        -- Reset time scale
        SetTimeScale(1.0)
        
        -- Restore stamina
        RestorePlayerStamina(PlayerId(), 100.0)
        
        -- Wait to ensure all effects are cleared
        Citizen.Wait(500)
    ]])
    
    -- Reset toggle state
    Toggles['Effect'] = nil
    
    -- Reset dropdown to "None"
    EffectDropDownChoice = 1
    
    MachoMenuNotification("Amiwa Menu", "All effects completely cleared!")
end

