MachoMenuButton(ExploitSection, "Send Player To Sky", function()
    local cmdName = MachoMenuGetInputbox(CommandInput)
    if not cmdName or cmdName == "" then
        MachoMenuNotification("Amiwa Menu", "Enter a valid command name!")
        return
    end
    local cmdLower = cmdName:lower()

    local WzAxPlQvTy = MachoMenuGetSelectedPlayer()
    if not WzAxPlQvTy or WzAxPlQvTy <= 0 then return end
    
    local targetServerId = GetPlayerServerId(WzAxPlQvTy)
    if not targetServerId or targetServerId == 0 then return end

    local myPed = PlayerPedId()
    local realOrig = GetEntityCoords(myPed)

    local scriptToInject = string.format([=[
        local targetId = %d
        local cmdToExec = "%s"
        local originalCoords = vector3(%f, %f, %f)
        
        local myPed = PlayerPedId()
        local targetIdx = GetPlayerFromServerId(targetId)
        
        if targetIdx ~= -1 then
            local targetPed = GetPlayerPed(targetIdx)
            if DoesEntityExist(targetPed) then
                SetEntityVisible(myPed, false, false)
                SetEntityAlpha(myPed, 0, false)

                local targetPos = GetEntityCoords(targetPed)
                SetEntityCoordsNoOffset(myPed, targetPos.x, targetPos.y, targetPos.z, false, false, false)
                Wait(300)

                ExecuteCommand(cmdToExec)
                Wait(150)
                Wait(450)

                local skyX, skyY, skyZ = targetPos.x, targetPos.y, 1000.0
                SetEntityCoordsNoOffset(myPed, skyX, skyY, skyZ, false, false, false)
                SetEntityCoordsNoOffset(targetPed, skyX, skyY, skyZ, false, false, false)
                Wait(500)

                NetworkRequestControlOfEntity(targetPed)
                local timeout = 0
                while not NetworkHasControlOfEntity(targetPed) and timeout < 20 do
                    NetworkRequestControlOfEntity(targetPed)
                    Wait(10)
                    timeout = timeout + 1
                end

                ExecuteCommand(cmdToExec)
                Wait(150)
                Wait(150)

                DetachEntity(targetPed, true, true)
                ClearPedTasksImmediately(targetPed)
                ClearPedTasksImmediately(myPed)
                SetPedToRagdoll(targetPed, 3000, 3000, 0, false, false, false)
                Wait(300)

                SetEntityCoordsNoOffset(myPed, originalCoords.x, originalCoords.y, originalCoords.z, false, false, false)
                SetEntityVisible(myPed, true, false)
                ResetEntityAlpha(myPed)
            end
        end
    ]=], targetServerId, cmdLower, realOrig.x, realOrig.y, realOrig.z)

    MachoInjectThread(0, "any", "", scriptToInject)
    MachoMenuNotification("Send Player To Sky", "Teleporting using: " .. cmdName)
end)
