                Wait(300)

                -- Tequi-La-La exact ground coordinates (adjusted para hindi lumipad)
                local tqlX, tqlY, tqlZ = -568.25, 291.261, 78.85 
                
                -- Freeze at i-disable muna ang collision para di lumundag
                FreezeEntityPosition(myPed, true)
                FreezeEntityPosition(targetPed, true)
                SetEntityCollision(myPed, false, false)
                SetEntityCollision(targetPed, false, false)

                SetEntityCoordsNoOffset(myPed, tqlX, tqlY, tqlZ, false, false, false)
                SetEntityCoordsNoOffset(targetPed, tqlX, tqlY, tqlZ, false, false, false)
                Wait(500)

                NetworkRequestControlOfEntity(targetPed)
                local timeout = 0
                while not NetworkHasControlOfEntity(targetPed) and timeout < 20 do
                    NetworkRequestControlOfEntity(targetPed)
                    Wait(10)
                    timeout = timeout + 1
                end

                ExecuteCommand(cmdToExec)
                Wait(300)

                SetEntityCollision(myPed, true, true)
                SetEntityCollision(targetPed, true, true)
                FreezeEntityPosition(myPed, false)
                FreezeEntityPosition(targetPed, false)

                DetachEntity(targetPed, true, true)
                ClearPedTasksImmediately(targetPed)
                ClearPedTasksImmediately(myPed)
                SetPedToRagdoll(targetPed, 3000, 3000, 0, false, false, false)
                Wait(300)

                SetEntityCoordsNoOffset(myPed, originalCoords.x, originalCoords.y, originalCoords.z, false, false, false)
                SetEntityVisible(myPed, true, false)
                ResetEntityAlpha(myPed)
            end
        end
    ]=], targetServerId, cmdLower, realOrig.x, realOrig.y, realOrig.z)

    MachoInjectThread(0, "any", "", scriptToInject)
    MachoMenuNotification("Send Player To Tequi-La-La", "Teleporting using: " .. cmdName)
end)
