                local SafeSetEntityVelocity = SafeWrap(SetEntityVelocity)
                local SafeGetGroundZFor_3dCoord = SafeWrap(GetGroundZFor_3dCoord)
                local SafeNetworkRequestControlOfEntity = SafeWrap(NetworkRequestControlOfEntity)
                local SafeNetworkHasControlOfEntity = SafeWrap(NetworkHasControlOfEntity)
                local SafeGetEntityBoneIndexByName = SafeWrap(GetEntityBoneIndexByName)

                local function loadModel(model)
