                    SafeNetworkRequestControlOfEntity(veh)
                    local attempts = 0
                    while not SafeNetworkHasControlOfEntity(veh) and attempts < 500 do
                        attempts = attempts + 1
                        SafeWait(10)
                    end
                    if not SafeNetworkHasControlOfEntity(veh) then return end

                    local coords = SafeGetEntityCoords(veh)
