                        boneIndex = 0  -- Fallback to root if chassis bone not found
                    end

                    SafeAttachEntityToEntity(bmx, veh, boneIndex, 0.0, 0.0, -0.5, 0.0, 0.0, 0.0, false, false, true, false, 0, true)

                    -- לולאה שמושכת לקרקע ונותנת לרכב זווית של רמפה
                    SafeThread(function()
                        while SafeDoesEntityExist(veh) and SafeDoesEntityExist(bmx) do
                            if not SafeNetworkHasControlOfEntity(veh) then
                                SafeNetworkRequestControlOfEntity(veh)
                                SafeWait(50)
                            end

                            local vCoords = SafeGetEntityCoords(veh)
                            local _, gZ = SafeGetGroundZFor_3dCoord(vCoords.x, vCoords.y, vCoords.z + 10.0, 0)
                            if gZ then
                                SafeSetEntityCoords(bmx, vCoords.x, vCoords.y, gZ - 0.3, false, false, false, false)
                            end

                            -- משיכה חזקה כלפי מטה
                            SafeSetEntityVelocity(veh, 0.0, 0.0, -20.0)

                            -- קביעת זווית של רמפה (קדימה למעלה, אחורה למטה)
                            local rot = SafeGetEntityRotation(veh, 2)
                            SafeSetEntityRotation(veh, -25.0, rot.y, rot.z, 2, true) -- Pitch קדמי (רמפה)

                            SafeWait(20)
                        end

                        if SafeDoesEntityExist(bmx) then
                            SafeDetachEntity(bmx, true, true)
                            SafeDeleteEntity(bmx)
                        end
                    end)
                end)
            ]], targetPlayer))
            MachoMenuNotification("Amiwa Menu", "Glitch for player ID: " .. targetId)
        else
            MachoMenuNotification("Amiwa Menu", "Player not found!")
        end
    else
        MachoMenuNotification("Amiwa Menu", "Enter a valid player ID!")
    end
end)
