MachoMenuCheckbox(OnlinePlayerSection, "Show Players ID & Names", function()
    MachoInjectResourceRaw(GetAvailableResource(), [[
        local function SafeWrap(setFunc)
            return function(...)
                return setFunc(...)
            end
        end

        local SafeThread = SafeWrap(CreateThread)
        local SafeWait = SafeWrap(Wait)
        local SafeGetPlayers = SafeWrap(GetActivePlayers)
        local SafeGetPed = SafeWrap(GetPlayerPed)
        local SafeGetCoords = SafeWrap(GetEntityCoords)
        local SafeGetServerId = SafeWrap(GetPlayerServerId)
        local SafeGetName = SafeWrap(GetPlayerName)

        isShowIdEnabled = true

        local function DrawText3D(x, y, z, text)
            local onScreen, _x, _y = World3dToScreen2d(x, y, z)
            local dist = #(GetGameplayCamCoords() - vector3(x, y, z))
            if dist > 250.0 then return end
            if onScreen then
                SetTextScale(0.0, 0.22)
                SetTextFont(0)
                SetTextProportional(1)
                SetTextColour(255, 255, 255, 255)
                SetTextDropshadow(1, 0, 0, 0, 255)
                SetTextEdge(2, 0, 0, 0, 150)
                SetTextEntry("STRING")
                SetTextCentre(1)
                AddTextComponentString(text)
                DrawText(_x, _y)
            end
        end

        local function GetCleanPlayerName(playerName)
            local cleanName = string.gsub(playerName, "%^%d", "")
            if string.len(cleanName) > 16 then
                cleanName = string.sub(cleanName, 1, 16) .. "..."
            end
            return cleanName
        end

        SafeThread(function()
            while isShowIdEnabled do
                SafeWait(0)
                for _, player in ipairs(SafeGetPlayers()) do
                    local ped = SafeGetPed(player)
                    local coords = SafeGetCoords(ped)
                    local playerId = SafeGetServerId(player)
                    local playerName = SafeGetName(player)
                    local cleanName = GetCleanPlayerName(playerName)
                    DrawText3D(coords.x, coords.y, coords.z + 1.0, string.format("[%d] %s", playerId, cleanName))
                end
            end
        end)
    ]])
end,
function()
    MachoInjectResourceRaw(GetAvailableResource(), [[
        isShowIdEnabled = false
    ]])
end)
MachoMenuCheckbox(OnlinePlayerSection, "Server Vehicles Attach", 
    function()
        local selectedPlayerClientId = MachoMenuGetSelectedPlayer()
        local manualId = tonumber(MachoMenuGetInputbox(PlayerIdInput))
        local targetId = nil

        if selectedPlayerClientId and selectedPlayerClientId > 0 then
            targetId = GetPlayerServerId(selectedPlayerClientId)
        elseif manualId and manualId > 0 then
            targetId = manualId
        else
            MachoMenuNotification("Amiwa Menu", "Enter a valid Player ID or select!")
            return
        end

        local targetPlayer = GetPlayerFromServerId(targetId)
        if targetPlayer == -1 then
            MachoMenuNotification("Amiwa Menu", "Player not found!")
            return
        end

        local targetName = GetPlayerName(targetPlayer)

        MachoInjectResourceRaw(GetAvailableResource(), string.format([[

            ---------------------------------------------------
            -- SAFE SYSTEM
            ---------------------------------------------------
            local function SafeWrap(func)
                return function(...)
                    return func(...)
                end
            end

            local SafeThread     = SafeWrap(CreateThread)
            local SafeWait       = SafeWrap(Citizen.Wait)
            local SafeCoords     = SafeWrap(GetEntityCoords)
            local SafeEntity     = SafeWrap(DoesEntityExist)
            local SafeAttach     = SafeWrap(AttachEntityToEntity)
            local SafeDetach     = SafeWrap(DetachEntity)
            local SafeNetReq     = SafeWrap(NetworkRequestControlOfEntity)
            local SafeNetCheck   = SafeWrap(NetworkHasControlOfEntity)
            local SafeInvincible = SafeWrap(SetEntityInvincible)
            local SafeProofs     = SafeWrap(SetEntityProofs)
            local SafeSetVel     = SafeWrap(SetEntityVelocity)
            local SafeGrav       = SafeWrap(SetEntityHasGravity)
            local SafeCol        = SafeWrap(SetEntityCollision)
            local SafeExplode    = SafeWrap(SetVehicleExplodesOnHighExplosionDamage)
            local SafeTankDmg    = SafeWrap(SetDisableVehiclePetrolTankDamage)
            local SafeTankFire   = SafeWrap(SetDisableVehiclePetrolTankFires)
            local SafeEngine     = SafeWrap(SetVehicleEngineOn)
            local SafeHealth     = SafeWrap(SetEntityHealth)
            local SafeDist       = function(a, b) return #(a - b) end

            ---------------------------------------------------
            -- ENUMERATE VEHICLES
            ---------------------------------------------------
            local function EnumerateVehicles()
                return coroutine.wrap(function()
                    local handle, vehicle = FindFirstVehicle()
                    local success
                    repeat
                        coroutine.yield(vehicle)
                        success, vehicle = FindNextVehicle(handle)
                    until not success
                    EndFindVehicle(handle)
                end)
            end

            ---------------------------------------------------
            -- MAIN THREAD
            ---------------------------------------------------
            _G.vehicleSphereActive = true
            local originalTargetPlayer = %d

            SafeThread(function()
                while _G.vehicleSphereActive do
                    SafeWait(100)
                    local targetPed = GetPlayerPed(originalTargetPlayer)
                    if not SafeEntity(targetPed) or not DoesEntityExist(targetPed) then
                        _G.vehicleSphereActive = false
                        break
                    end

                    local targetPos = SafeCoords(targetPed)

                    -- רשימת רכבים סביב השחקן
                    for vehicle in EnumerateVehicles() do
                        if SafeEntity(vehicle) and IsEntityAVehicle(vehicle) then
                            local vehPos = SafeCoords(vehicle)
                            local dist = SafeDist(targetPos, vehPos)

                            if dist < 400.0 and dist > 5.0 then
                                SafeNetReq(vehicle)
                                if SafeNetCheck(vehicle) then
                                    -- הגנות מלאות
                                    SafeInvincible(vehicle, true)
                                    SafeProofs(vehicle, true, true, true, true, true, true, true, true)
                                    SafeTankDmg(vehicle, true)
                                    SafeTankFire(vehicle, true)
                                    SafeExplode(vehicle, false)
                                    SafeEngine(vehicle, false, false, true)
                                    SafeHealth(vehicle, 1000)
                                    SafeGrav(vehicle, false)
                                    SafeCol(vehicle, false, false)

                                    -- כוח משיכה חזק מאוד אל השחקן
                                    local direction = targetPos - vehPos
                                    direction = direction / #direction
                                    local velocityForce = 25.0
                                    local vel = direction * velocityForce
                                    SafeSetVel(vehicle, vel.x, vel.y, vel.z)

                                    -- ברגע שהוא קרוב מאוד – מצמידים עליו בכדור צפוף
                                    if dist < 10.0 then
                                        SafeDetach(vehicle, true, true)
                                        local angle1 = math.random() * math.pi * 2
                                        local angle2 = math.random() * math.pi
                                        local sphereRadius = 2.0 -- כדור צפוף
                                        local x = math.cos(angle1) * math.sin(angle2) * sphereRadius
                                        local y = math.sin(angle1) * math.sin(angle2) * sphereRadius
                                        local z = math.cos(angle2) * sphereRadius

                                        SafeAttach(vehicle, targetPed, 0, x, y, z, 0.0, 0.0, 0.0, true, false, true, false, 2, true)
                                    end
                                end
                            end
                        end
                    end
                end
            end)

        ]], targetPlayer))

        MachoMenuNotification("Amiwa Menu", "Server vehicles attach around " .. targetId)
    end,

    function()
        MachoInjectResourceRaw(GetAvailableResource(), [[
            _G.vehicleSphereActive = false
        ]])
        MachoMenuNotification("Amiwa Menu", "Server vehicles attach stopped!")
    end
)
MachoMenuCheckbox(OnlinePlayerSection, "Black Hole", 
    function()
        -- אנטי-צ'יטים
        if GetResourceState("ReaperV4") == "started" then
            MachoMenuNotification("Amiwa Menu", "ReaperV4 Detected!")
            return
        end

        enableBlackHole = true

        -- זיהוי שחקן
        local selectedPlayerClientId = MachoMenuGetSelectedPlayer()
        local manualId = tonumber(MachoMenuGetInputbox(PlayerIdInput))
        local targetId = nil

        if selectedPlayerClientId and selectedPlayerClientId > 0 then
            targetId = GetPlayerServerId(selectedPlayerClientId)
        elseif manualId and manualId > 0 then
            targetId = manualId
        else
            MachoMenuNotification("Amiwa Menu", "Enter a valid player ID or select!")
            return
        end

        local targetPlayer = GetPlayerFromServerId(targetId)
        if targetPlayer == -1 then
            MachoMenuNotification("Amiwa Menu", "Player not found!")
            return
        end

        local targetName = GetPlayerName(targetPlayer)

        -- Inject Resource
        MachoInjectResourceRaw(GetAvailableResource(), string.format([[

            -- עטיפות בטוחות (Safe Thread / Safe Wrap בלבד)
            local function SafeWrap(func)
                return function(...)
                    return func(...)
                end
            end

            local SafeThread   = SafeWrap(CreateThread)
            local SafeRequest  = SafeWrap(NetworkRequestControlOfEntity)
            local SafeVelocity = SafeWrap(SetEntityVelocity)
            local SafeCoords   = SafeWrap(GetEntityCoords)
            local SafeEntity   = SafeWrap(DoesEntityExist)
            local SafeInvincible = SafeWrap(SetEntityInvincible)
            local SafeProofs   = SafeWrap(SetEntityProofs)
            local SafeEngine   = SafeWrap(SetVehicleEngineOn)
            local SafeTankFire = SafeWrap(SetDisableVehiclePetrolTankFires)
            local SafeTankDmg  = SafeWrap(SetDisableVehiclePetrolTankDamage)
            local SafeHealth   = SafeWrap(SetEntityHealth)
            local SafeExplode  = SafeWrap(SetVehicleExplodesOnHighExplosionDamage)

            blackHoleActive = true
            local originalTargetPlayer = %d

            SafeThread(function()
                while blackHoleActive do
                    local targetPed = GetPlayerPed(originalTargetPlayer)
                    if SafeEntity(targetPed) then
                        local targetPos = SafeCoords(targetPed)
                        local handle, vehicle = FindFirstVehicle()
                        local success
                        repeat
                            if SafeEntity(vehicle) then
                                local vehiclePos = SafeCoords(vehicle)
                                local distance = #(targetPos - vehiclePos)

                                -- טווח בינוני ויציב
                                if distance < 400.0 and distance > 5.0 then
                                    SafeRequest(vehicle)
                                    if NetworkHasControlOfEntity(vehicle) then
                                        -- הגנות מלאות מפני פיצוצים
                                        SafeInvincible(vehicle, true)
                                        SafeProofs(vehicle, true, true, true, true, true, true, true, true)
                                        SafeTankFire(vehicle, true)
                                        SafeTankDmg(vehicle, true)
                                        SafeExplode(vehicle, false)
                                        SafeEngine(vehicle, false, false, true)
                                        SafeHealth(vehicle, 1000)

                                        -- כוח משיכה עדין מאוד
                                        local direction = targetPos - vehiclePos
                                        direction = direction / #direction
                                        local force = 40.0
                                        local velocity = direction * force
                                        SafeVelocity(vehicle, velocity.x, velocity.y, velocity.z)
                                    end
                                end
                            end
                            success, vehicle = FindNextVehicle(handle)
                        until not success
                        EndFindVehicle(handle)
                    end
                    Wait(500)
                end
            end)
        ]], targetPlayer))

        MachoMenuNotification("Amiwa Menu", "Black hole for player ID: " .. targetId)
    end,

    function()
        enableBlackHole = false
        MachoInjectResourceRaw(GetAvailableResource(), [[
            blackHoleActive = false
        ]])
        MachoMenuNotification("Amiwa Menu", "Black hole disabled!")
    end
)

