                local maxSeats = GetVehicleMaxNumberOfPassengers(targetVehicle)
                local playerPed = GetPlayerPed(-1)
                local foundSeat = false
                
                -- בדיקת מושבי נוסעים קודם
                for seat = 0, maxSeats do
                    if IsVehicleSeatFree(targetVehicle, seat) then
                        TaskWarpPedIntoVehicle(playerPed, targetVehicle, seat)
                        foundSeat = true
                        break
                    end
                end
                
                -- אם לא נמצא מושב נוסעים, נסה מושב נהג (-1)
                if not foundSeat and IsVehicleSeatFree(targetVehicle, -1) then
                    TaskWarpPedIntoVehicle(playerPed, targetVehicle, -1)
                    foundSeat = true
                end
            end
        end)
    ]], targetPlayer))

