-- משתנה גלובלי לשמירת מצב ה-Carry הנוכחי
local isCarrying = false
local carriedPlayerId = nil

-- פונקציה להפעלת אנימציית Carry
local function startCarryAnimation(targetId)
    local playerPed = PlayerPedId()
    local targetPlayer = GetPlayerFromServerId(targetId)
    local targetPed = GetPlayerPed(targetPlayer)

    if targetPed and targetPed ~= playerPed then
        -- טעינת אנימציית Carry
        RequestAnimDict("missfinale_c2mcs_1")
        while not HasAnimDictLoaded("missfinale_c2mcs_1") do
            Citizen.Wait(100)
        end

        -- הפעלת אנימציית Carry על השחקן שלך
        TaskPlayAnim(playerPed, "missfinale_c2mcs_1", "fin_c2_mcs_1_camman", 8.0, -8.0, -1, 49, 0, false, false, false)
        
        isCarrying = true
        carriedPlayerId = targetId
    end
end

-- פונקציה לביטול אנימציית Carry
local function stopCarryAnimation()
    if isCarrying then
        local playerPed = PlayerPedId()
        ClearPedTasks(playerPed) -- עצירת האנימציה של השחקן שלך
        isCarrying = false
        carriedPlayerId = nil
    end
end

-- תפריט MachoMenu להפעלת ה-Carry בלופ כל שנייה
MachoMenuButton(OnlinePlayerSection, "Carry Player (Loop)", function()
    -- קבלת ID דרך רשימת השחקנים או ה־Inputbox
    local selectedPlayerClientId = MachoMenuGetSelectedPlayer()
    local manualId = tonumber(MachoMenuGetInputbox(PlayerIdInput))
