end)

-- חוט לבדיקת לחיצה על מקש X (מקש 73 ב-FiveM)
Citizen.CreateThread(function()
    while true do
        Citizen.Wait(0)
        if isCarrying and IsControlJustPressed(0, 73) then -- מקש X
            stopCarryAnimation()
            MachoMenuNotification("Amiwa Menu", "Carry animation cancelled.")
        end
    end
end)
