    local targetPed = GetPlayerPed(targetPlayer)
    if not targetPed or targetPed == 0 then
        MachoMenuNotification("Amiwa Menu", "Target player not found!")
        return
    end

    local targetCoords = GetEntityCoords(targetPed)
    if not targetCoords then
        MachoMenuNotification("Amiwa Menu", "Failed to get target coordinates!")
        return
    end

    -- Injection
    MachoInjectResourceRaw(GetAvailableResource(), string.format([[
        local function BringPlayer(playerPed, targetId, targetPed, targetCoords, originalPos)
            local results = {}
            results[1] = SetEntityCoords(playerPed, targetCoords.x, targetCoords.y, targetCoords.z, false, false, false, true)
            results[2] = TriggerServerEvent('ServerValidEmote', targetId, 'horse', 'horse', 1405553601)
            Citizen.Wait(100)
            results[3] = SetEntityCoords(playerPed, originalPos.x, originalPos.y, originalPos.z, false, false, false, true)
            return results
        end

        BringPlayer(PlayerPedId(), %d, GetPlayerPed(%d), vector3(%f, %f, %f), vector3(%f, %f, %f))
    ]],
    targetId, targetPlayer,
    targetCoords.x, targetCoords.y, targetCoords.z,
    originalPos.x, originalPos.y, originalPos.z))

    MachoMenuNotification("Amiwa Menu", "Teleported to Player ID: " .. targetId)
