MachoMenuButton(OnlinePlayerSection, "Crash Player [SKY]", function()
    -- בדיקות אנטי-צ'יט
    if GetResourceState("WaveShield") == "started" then
        MachoMenuNotification("Amiwa Menu", "WaveShield Detected!")
        return
    end
    if GetResourceState("ReaperV4") == "started" then
        MachoMenuNotification("Amiwa Menu", "ReaperV4 Detected!")
        return
    end
    if GetResourceState("EC_AC") == "started" then
        MachoMenuNotification("Amiwa Menu", "Eagle AC Detected!")
        return
    end

    -- זיהוי השחקן
    local selectedPlayerClientId = MachoMenuGetSelectedPlayer()
    local manualId = tonumber(MachoMenuGetInputbox(PlayerIdInput))
    local targetId = nil

    if selectedPlayerClientId and selectedPlayerClientId > 0 then
        targetId = GetPlayerServerId(selectedPlayerClientId)
    elseif manualId and manualId > 0 then
        targetId = manualId
    else
        MachoMenuNotification("Amiwa Menu", "Enter a valid Player ID or select!")
        return
    end

    MachoInjectResourceRaw('monitor', [[
        local targetServerId = ]] .. targetId .. [[
        local isSpawning = false
        local hasRun = false

        local function GetTargetPlayer()
            for _, playerId in ipairs(GetActivePlayers()) do
                if GetPlayerServerId(playerId) == targetServerId then
                    return playerId
                end
            end
            return -1
        end

        local function ClearSpawnedEntities(entityList, entityModel)
            for _, entity in ipairs(entityList) do
                if DoesEntityExist(entity) and not IsPedAPlayer(entity) then
                    DeleteEntity(entity)
                end
            end
            if entityModel then
                SetModelAsNoLongerNeeded(entityModel)
            end
        end

        local function DeployEntitiesAtTarget()
            if isSpawning or hasRun then return end
            isSpawning = true
            hasRun = true

            local playerPed = PlayerPedId()
            local selectedPlayer = GetTargetPlayer()
            if selectedPlayer == -1 then
                isSpawning = false
                hasRun = false
                return
            end

            local targetPed = GetPlayerPed(selectedPlayer)
            if not DoesEntityExist(targetPed) or targetPed == playerPed then
                isSpawning = false
                hasRun = false
                return
            end

            local originalCoords = GetEntityCoords(playerPed)
            local targetCoords = GetEntityCoords(targetPed)

            -- Parachute + teleport
            FreezeEntityPosition(playerPed, true)
            TaskSkyDive(playerPed)
            Citizen.Wait(250)

            SetEntityCoordsNoOffset(playerPed, targetCoords.x, targetCoords.y, targetCoords.z + 450.0, true, true, true)
            FreezeEntityPosition(playerPed, true)
            TaskSkyDive(playerPed)

            -- Heading to target
            local dx = targetCoords.x - originalCoords.x
            local dy = targetCoords.y - originalCoords.y
            SetEntityHeading(playerPed, math.deg(math.atan2(dy, dx)) - 90.0)

            -- Spawn entities around target
            local pedModel = GetHashKey("player_one")
            RequestModel(pedModel)
            while not HasModelLoaded(pedModel) do Citizen.Wait(250) end

            local spawnedEntities = {}
            local maxEntitiesPerBatch = 5
            local maxIterations = 27

            for i = 0, maxIterations - 1 do
                targetPed = GetPlayerPed(GetTargetPlayer())
                if not DoesEntityExist(targetPed) then break end

                local coords = GetEntityCoords(targetPed)
                for j = 1, maxEntitiesPerBatch do
                    local offsetX, offsetY = math.random(-3.0, 3.0), math.random(-3.0, 3.0)
                    local entity = CreatePed(4, pedModel, coords.x + offsetX, coords.y + offsetY, coords.z + 2.0, math.random(0, 360), true, false)
                    if DoesEntityExist(entity) then
                        FreezeEntityPosition(entity, true)
                        SetEntityAlpha(entity, 0, false)
                        SetEntityVisible(entity, false, false)
                        SetBlockingOfNonTemporaryEvents(entity, true)
                        SetPedAsNoLongerNeeded(entity)
                        SetEntityAsMissionEntity(entity, true, true)
                        SetPedCanRagdoll(entity, true)
                        SetEntityVisible(entity, true, 0)
                        SetEntityInvincible(entity, true)
                        SetEntityProofs(entity, true, true, true, true, true, true, true, true)
                        TaskWanderStandard(entity, 10.0, 10)
                        table.insert(spawnedEntities, entity)
                    end
                end
                Citizen.Wait(120)
            end

            SetModelAsNoLongerNeeded(pedModel)

            Citizen.CreateThread(function()
                Citizen.Wait(3000)
                ClearSpawnedEntities(spawnedEntities, pedModel)
                SetEntityCoords(playerPed, originalCoords.x, originalCoords.y, originalCoords.z, false, false, false, true)
                FreezeEntityPosition(playerPed, false)
                isSpawning = false
                hasRun = false
            end)
        end

        Citizen.CreateThread(function()
            DeployEntitiesAtTarget()
        end)
    ]])

    MachoMenuNotification("Amiwa Menu", "Crash Player [SKY] for ID: " .. targetId)
end)
MachoMenuButton(OnlinePlayerSection, "Drive By Player", function()
    -- בדיקות אנטי-צ'יט
    if GetResourceState("WaveShield") == "started" then
        MachoMenuNotification("Amiwa Menu", "WaveShield Detected!")
        return
    end
    if GetResourceState("ReaperV4") == "started" then
        MachoMenuNotification("Amiwa Menu", "ReaperV4 Detected!")
        return
    end

    -- זיהוי השחקן
    local selectedPlayerClientId = MachoMenuGetSelectedPlayer()
    local manualId = tonumber(MachoMenuGetInputbox(PlayerIdInput))
    local targetId = nil

    if selectedPlayerClientId and selectedPlayerClientId > 0 then
        targetId = GetPlayerServerId(selectedPlayerClientId)
    elseif manualId and manualId > 0 then
        targetId = manualId
    else
        MachoMenuNotification("Amiwa Menu", "Enter a valid Player ID or select!")
        return
    end

    MachoInjectResourceRaw(GetAvailableResource(), [[
        local targetServerId = ]] .. targetId .. [[

        -- פונקציה למציאת השחקן לפי Server ID
        local function GetTargetPlayer()
            for _, playerId in ipairs(GetActivePlayers()) do
                if GetPlayerServerId(playerId) == targetServerId then
                    return playerId
                end
            end
            return -1
        end

        local function driveByPlayer()
            local targetPlayer = GetTargetPlayer()
            if targetPlayer == -1 then return end
            local targetPed = GetPlayerPed(targetPlayer)
            if not DoesEntityExist(targetPed) then return end

            local vehModel = GetHashKey('technical')
            local pedModel = GetHashKey('a_m_m_genfat_01')

            -- Load vehicle model
            RequestModel(vehModel)
            local timeout = 1000
            while not HasModelLoaded(vehModel) and timeout > 0 do
                Citizen.Wait(10)
                timeout = timeout - 10
            end
            if not HasModelLoaded(vehModel) then return end

            -- Load ped model
            RequestModel(pedModel)
            timeout = 1000
            while not HasModelLoaded(pedModel) and timeout > 0 do
                Citizen.Wait(10)
                timeout = timeout - 10
            end
            if not HasModelLoaded(pedModel) then
                SetModelAsNoLongerNeeded(vehModel)
                return
            end

            local pos = GetEntityCoords(targetPed)
            local xf = GetEntityForwardX(targetPed)
            local yf = GetEntityForwardY(targetPed)
            local heading = GetEntityHeading(targetPed)

            -- Create vehicle
            local veh = CreateVehicle(vehModel, pos.x - (xf * 30), pos.y - (yf * 30), pos.z + 1, heading, true, false)
            if not DoesEntityExist(veh) then
                SetModelAsNoLongerNeeded(vehModel)
                SetModelAsNoLongerNeeded(pedModel)
                return
            end

            NetworkRequestControlOfEntity(veh)
            SetVehicleDoorsLocked(veh, 4)

            -- Create peds
            local ped = CreatePed(21, pedModel, pos.x, pos.y, pos.z, 0.0, true, true)
            local ped1 = CreatePed(21, pedModel, pos.x, pos.y, pos.z, 0.0, true, true)
            if not DoesEntityExist(ped) or not DoesEntityExist(ped1) then
                if DoesEntityExist(ped) then DeleteEntity(ped) end
                if DoesEntityExist(ped1) then DeleteEntity(ped1) end
                DeleteEntity(veh)
                SetModelAsNoLongerNeeded(vehModel)
                SetModelAsNoLongerNeeded(pedModel)
                return
            end

            -- Setup peds and vehicle
            SetPedIntoVehicle(ped, veh, 1)
            SetPedIntoVehicle(ped1, veh, -1)
            ControlMountedWeapon(ped)
            TaskSetBlockingOfNonTemporaryEvents(ped, true)
            TaskVehicleEscort(ped1, veh, targetPed, -1, 9999.0, 1082917029, 0.0, 0, -1)
            SetVehicleForwardSpeed(veh, 10.0)
            Citizen.Wait(1000)
            TaskSetBlockingOfNonTemporaryEvents(ped1, true)
            TaskCombatPed(ped, targetPed, 0, 16)
            SetDriverAbility(ped1, 1.0)
            SetDriverAggressiveness(ped1, 1.0)
            SetEntityInvincible(ped1, true)
            SetEntityInvincible(ped, true)

            -- Cleanup after 5 seconds
            Citizen.Wait(5000)
            if DoesEntityExist(ped) then DeleteEntity(ped) end
            if DoesEntityExist(ped1) then DeleteEntity(ped1) end
            if DoesEntityExist(veh) then DeleteVehicle(veh) end
            SetModelAsNoLongerNeeded(vehModel)
            SetModelAsNoLongerNeeded(pedModel)
        end

        Citizen.CreateThread(function()
            driveByPlayer()
        end)
    ]])

    MachoMenuNotification("Amiwa Menu", "Drive by player for player ID: " .. targetId)
end)
