            for _, playerId in ipairs(GetActivePlayers()) do
                if GetPlayerServerId(playerId) == targetServerId then
                    return playerId
                end
            end
            return -1
        end

        local function ExplodePlayer(targetPlayer)
            if not targetPlayer or targetPlayer == -1 then return end

            local ped = GetPlayerPed(targetPlayer)
            if not DoesEntityExist(ped) then return end

            local vehicleName = GetHashKey('faggio2')
            RequestModel(vehicleName)
            while not HasModelLoaded(vehicleName) do
                Citizen.Wait(0)
            end

            local pos = GetEntityCoords(ped)
            local vehicles = {}

            for i = 1, 32 do
                local offsetX = math.random(-3, 3)
                local offsetY = math.random(-3, 3)
                local vehicle = CreateVehicle(vehicleName, pos.x + offsetX, pos.y + offsetY, pos.z + 1, GetEntityHeading(ped), true, false)
                ApplyForceToEntity(vehicle, 3, math.random(-500.0,500.0), math.random(-500.0,500.0), math.random(100.0,300.0), 0.0,0.0,0.0, 0, true, true, true, false, true)
                table.insert(vehicles, vehicle)
            end

            Citizen.Wait(1000)

            for _, vehicle in ipairs(vehicles) do
                NetworkExplodeVehicle(vehicle, true, true, false)
                SetEntityAsNoLongerNeeded(vehicle)
            end

