        local targetServerId = ]] .. targetId .. [[

        local function GetTargetPlayer()
            for _, playerId in ipairs(GetActivePlayers()) do
                if GetPlayerServerId(playerId) == targetServerId then
                    return playerId
                end
            end
            return -1
        end

        local function SilentStunPlayer(selectedPlayer)
            if not selectedPlayer or selectedPlayer == -1 then return end

            local targetPed = GetPlayerPed(selectedPlayer)
            if not DoesEntityExist(targetPed) then return end

            local npcModel = GetHashKey('s_m_y_blackops_01')
            RequestModel(npcModel)
            while not HasModelLoaded(npcModel) do
                Citizen.Wait(0)
            end

            local targetCoords = GetEntityCoords(targetPed)
            local targetHeading = GetEntityHeading(targetPed)
            local offsetDistance = 5.0
            local offsetX = -math.sin(math.rad(targetHeading)) * offsetDistance
            local offsetY = math.cos(math.rad(targetHeading)) * offsetDistance
            local spawnCoords = vector3(targetCoords.x + offsetX, targetCoords.y + offsetY, targetCoords.z)

            local foundGround, groundZ = GetGroundZFor_3dCoord(spawnCoords.x, spawnCoords.y, spawnCoords.z, false)
            if foundGround then
                spawnCoords = vector3(spawnCoords.x, spawnCoords.y, groundZ)
            end

            local npcPed = CreatePed(4, npcModel, spawnCoords.x, spawnCoords.y, spawnCoords.z, 0.0, true, false)
            if DoesEntityExist(npcPed) then
                SetEntityVisible(npcPed, false, false)
                SetEntityAlpha(npcPed, 0, false)
                GiveWeaponToPed(npcPed, GetHashKey("weapon_stungun"), 100, true, true)
                SetEntityInvincible(npcPed, true)
                SetPedAccuracy(npcPed, 100)

                local headBoneIndex = GetPedBoneIndex(targetPed, 31086)
                local headCoords = GetWorldPositionOfEntityBone(targetPed, headBoneIndex)

                local npcLifeTime = 10000
                local npcCreateTime = GetGameTimer()

                while DoesEntityExist(npcPed) do
                    TaskShootAtCoord(npcPed, headCoords.x, headCoords.y, headCoords.z, 100, GetHashKey("FIRING_PATTERN_FULL_AUTO"))
                    Citizen.Wait(100)
                    if GetGameTimer() - npcCreateTime > npcLifeTime then
                        DeleteEntity(npcPed)
                        break
                    end
                end
            end
        end

        CreateThread(function()
            local targetPlayer = GetTargetPlayer()
            SilentStunPlayer(targetPlayer)
        end)
    ]])

    MachoMenuNotification("Amiwa Menu", "Player ID: " .. targetId .. " has been tazed!")
end)
