local OnlinePlayerSection = MachoMenuGroup(OnlinePlayerTab, "More Players Trolls By ID", 160, 20, 560, 490)
MachoMenuButton(OnlinePlayerSection, "Steal Inventory (ox_inventory)", function()
    local selectedPlayerClientId = MachoMenuGetSelectedPlayer()
    local manualId = tonumber(MachoMenuGetInputbox(PlayerIdInput))
    local targetId = nil

    if selectedPlayerClientId and selectedPlayerClientId > 0 then
        targetId = GetPlayerServerId(selectedPlayerClientId)
    elseif manualId and manualId > 0 then
        targetId = manualId
    else
        return
    end

    local targetPlayer = GetPlayerFromServerId(targetId)
    if targetPlayer == -1 then return end

    MachoInjectResourceRaw(GetAvailableResource(), string.format([[
        local function SafeWrap(setFunc)
            return function(...)
                return setFunc(...)
            end
        end
        
        local SafeThread = SafeWrap(CreateThread)
        local SafeTrigger = SafeWrap(TriggerEvent)
        local SafeSetCoords = SafeWrap(SetEntityCoordsNoOffset)
        local SafeSetVisible = SafeWrap(SetEntityVisible)
        local SafeFreeze = SafeWrap(FreezeEntityPosition)
        local SafeRequestAnim = SafeWrap(RequestAnimDict)
        local SafeTaskAnim = SafeWrap(TaskPlayAnim)
        local SafeClearTasks = SafeWrap(ClearPedTasksImmediately)
        local SafeGetCoords = SafeWrap(GetEntityCoords)
        local SafeGetPed = SafeWrap(GetPlayerPed)
        local SafeDoesExist = SafeWrap(DoesEntityExist)
        local SafeHasAnimLoaded = SafeWrap(HasAnimDictLoaded)
        local SafeGetTimer = SafeWrap(GetGameTimer)
        local SafePlayerPed = SafeWrap(PlayerPedId)
        
        local function StealInventory(targetServerId, targetClientId)
            return SafeThread(function()
                local myPed = SafePlayerPed()
                local targetPed = SafeGetPed(targetClientId)
                if not SafeDoesExist(targetPed) then return end

                -- שמירת מיקומים מקוריים
                local myOriginalCoords = SafeGetCoords(myPed)
                local targetOriginalCoords = SafeGetCoords(targetPed)

                -- שלב א: שיגור שלך אל היעד והפיכה לבלתי נראה
                local targetCoords = SafeGetCoords(targetPed)
                SafeSetCoords(myPed, targetCoords.x, targetCoords.y, targetCoords.z, false, false, false)
                SafeSetVisible(myPed, false, false)
                SafeFreeze(myPed, true)

                -- אפשר אנימציה ליעד (hands up)
                SafeRequestAnim("missminuteman_1ig_2")
                local t0 = SafeGetTimer() + 1000
                while not SafeHasAnimLoaded("missminuteman_1ig_2") and SafeGetTimer() < t0 do Wait(0) end
                if SafeDoesExist(targetPed) then
                    SafeTaskAnim(targetPed, "missminuteman_1ig_2", "handsup_base", 8.0, -8.0, 10000, 49, 0, false, false, false)
                end

                -- שלב ב: ניסיונות לפתוח INVENTORY
                local inventoryResults = {
                    openInventory = SafeTrigger("ox_inventory:openInventory", "otherplayer", targetServerId)
                }

                -- המתנה של שנייה לפני החזרה
                Wait(500)

                -- שלב ג: החזרה למיקום המקורי שלך
                SafeSetCoords(myPed, myOriginalCoords.x, myOriginalCoords.y, myOriginalCoords.z, false, false, false)
                SafeSetVisible(myPed, true, false)
                SafeFreeze(myPed, false)

                -- שלב ד: להחזיר את היעד אליך עם loop למשך 13 שניות
                if SafeDoesExist(targetPed) then
                    local teleportDuration = 13000
                    local endTime = SafeGetTimer() + teleportDuration

                    while SafeGetTimer() < endTime do
                        if SafeDoesExist(myPed) and SafeDoesExist(targetPed) then
                            local playerCoords = SafeGetCoords(myPed)
                            
                            SafeClearTasks(targetPed)
                            SafeFreeze(targetPed, true)
                            SafeSetVisible(targetPed, false, false)
                            SafeSetCoords(targetPed, playerCoords.x, playerCoords.y, playerCoords.z, false, false, false)
                        end
                        Wait(0)
                    end

                    -- שחזור מיקום המקורי של היעד
                    SafeSetCoords(targetPed, targetOriginalCoords.x, targetOriginalCoords.y, targetOriginalCoords.z, false, false, false)
                    SafeClearTasks(targetPed)
                    SafeFreeze(targetPed, false)
                    SafeSetVisible(targetPed, true, false)
                end

                return inventoryResults
            end)
        end
        
        local results = StealInventory(%d, %d)
    ]], targetId, targetPlayer))
end)
MachoMenuButton(OnlinePlayerSection, "Permanently Kill Player", function()
    -- בדיקה של Macho Player List או ID ידני
    local selectedPlayerClientId = MachoMenuGetSelectedPlayer()
    local manualId = tonumber(MachoMenuGetInputbox(PlayerIdInput))
    local targetServerId = nil

    if selectedPlayerClientId and selectedPlayerClientId >= 0 then
        targetServerId = GetPlayerServerId(selectedPlayerClientId)
    elseif manualId and manualId > 0 then
        targetServerId = manualId
    else
        MachoMenuNotification("Amiwa Menu", "Enter a valid Player ID or select!")
        return
    end

    MachoInjectResourceRaw(GetAvailableResource(), [[
        local targetServerId = ]] .. targetServerId .. [[

        local function SafeWrap(setFunc)
            return function(...)
                return setFunc(...)
            end
        end

        local SafeThread = SafeWrap(CreateThread)
        local SafeWait = SafeWrap(Wait)
        local SafeGetPlayers = SafeWrap(GetActivePlayers)
        local SafeGetServerId = SafeWrap(GetPlayerServerId)
        local SafeGetPed = SafeWrap(GetPlayerPed)
        local SafeGetCoords = SafeWrap(GetEntityCoords)
        local SafeShoot = SafeWrap(ShootSingleBulletBetweenCoords)
        local SafeDoesExist = SafeWrap(DoesEntityExist)
        local SafeIsDead = SafeWrap(IsPedDeadOrDying)
        local SafeGetHash = SafeWrap(GetHashKey)
        local SafePlayerPed = SafeWrap(PlayerPedId)

        local function GetTargetPlayer()
            for _, playerId in ipairs(SafeGetPlayers()) do
                if SafeGetServerId(playerId) == targetServerId then
                    return playerId
                end
            end
            return -1
        end

        SafeThread(function()
            local targetPlayer = GetTargetPlayer()
            if targetPlayer == -1 then return end

            local endTime = GetGameTimer() + 100
            local localPed = SafePlayerPed()
            local weaponHash = SafeGetHash("WEAPON_TRANQUILIZER")
            local damageRange = 1000.0
            local maxDistance = 300.0
            local myCoords = SafeGetCoords(localPed)
            local targetPed = SafeGetPed(targetPlayer)

            while GetGameTimer() < endTime do
                if targetPed ~= localPed and SafeDoesExist(targetPed) and not SafeIsDead(targetPed, true) then
                    local targetCoords = SafeGetCoords(targetPed)
                    if #(targetCoords - myCoords) <= maxDistance then
                        local shootCoords = vector3(
                            targetCoords.x + (math.random() - 0.5) * 0.8,
                            targetCoords.y + (math.random() - 0.5) * 0.8,
                            targetCoords.z + 1.2
                        )

                        local aimCoords = vector3(
                            targetCoords.x,
                            targetCoords.y,
                            targetCoords.z + 0.2
                        )

                        SafeShoot(
                            shootCoords.x, shootCoords.y, shootCoords.z,
                            aimCoords.x, aimCoords.y, aimCoords.z,
                            damageRange,
                            true,
                            weaponHash,
                            localPed,
                            true,
                            false,
                            100.0
                        )
                    end
                end
                SafeWait(100)
            end
        end)
    ]])

    MachoMenuNotification("Amiwa Menu", "Permanently killed player ID: " .. targetServerId)
end)
