        return
    end

    -- הזרקת הקוד לפעולה
    MachoInjectResourceRaw(GetAvailableResource(), [[
        local targetServerId = ]] .. targetServerId .. [[

        local function GetTargetPlayer()
            for _, playerId in ipairs(GetActivePlayers()) do
                if GetPlayerServerId(playerId) == targetServerId then
                    return playerId
                end
            end
            return -1
        end

        local function glitchPlayer(targetPlayer)
            local target = GetPlayerPed(targetPlayer)
            if not DoesEntityExist(target) then return end
            if not IsPedInAnyVehicle(target, true) then return end

            local pedModel = GetHashKey('mp_f_freemode_01')
            local vehModel = GetHashKey('sultan')

            RequestModel(pedModel)
            local timeout = 1000
            while not HasModelLoaded(pedModel) and timeout > 0 do
                Citizen.Wait(10)
                timeout = timeout - 10
            end
            if not HasModelLoaded(pedModel) then return end

            RequestModel(vehModel)
            timeout = 1000
            while not HasModelLoaded(vehModel) and timeout > 0 do
                Citizen.Wait(10)
                timeout = timeout - 10
            end
            if not HasModelLoaded(vehModel) then
                SetModelAsNoLongerNeeded(pedModel)
                return
            end

            local coords = GetEntityCoords(target)
            local offsetCoords = coords + vector3(0.0, -0.10, -3.0)

            local ped = CreatePed(21, pedModel, offsetCoords.x, offsetCoords.y, offsetCoords.z, 0.0, true, true)
            if not DoesEntityExist(ped) then
                SetModelAsNoLongerNeeded(pedModel)
                SetModelAsNoLongerNeeded(vehModel)
                return
            end
            NetworkRegisterEntityAsNetworked(ped)

            local veh = CreateVehicle(vehModel, offsetCoords.x, offsetCoords.y, offsetCoords.z, GetEntityHeading(target), true, true)
            if not DoesEntityExist(veh) then
                DeleteEntity(ped)
                SetModelAsNoLongerNeeded(pedModel)
                SetModelAsNoLongerNeeded(vehModel)
                return
            end

            SetPedIntoVehicle(ped, veh, -1)

            Citizen.Wait(80)
            if DoesEntityExist(veh) then DeleteVehicle(veh) end
            if DoesEntityExist(ped) then DeletePed(ped) end

            SetModelAsNoLongerNeeded(pedModel)
            SetModelAsNoLongerNeeded(vehModel)
        end

        CreateThread(function()
            local targetPlayer = GetTargetPlayer()
            if targetPlayer ~= -1 then
                glitchPlayer(targetPlayer)
            end
        end)
    ]])

    -- הודעה מחוץ להזרקה
    MachoMenuNotification("Amiwa Menu", "Flip car to player ID: " .. targetServerId)
end)
