MachoMenuButton(WeaponsSection, "Spoof Weapon", function()
    if GetResourceState("ReaperV44343") == "started" then
        MachoMenuNotification("Amiwa Menu", "ReaperV4 Detected!")
        return
    end

    local WeaponName = MachoMenuGetInputbox(WeaponInput)
    if not WeaponName or WeaponName == "" then
        MachoMenuNotification("Amiwa Menu", "Enter a valid weapon name!")
        return
    end

    local weaponLower = WeaponName:lower()

    MachoInjectResourceRaw("any", string.format([[
        local function Rm_Safe()
            local function sA6(func)
                return function(...)
                    return func(...)
                end
            end

            local sT7 = sA6(Citizen.CreateThread)
            local gP1 = sA6(PlayerPedId)
            local gW2 = sA6(GiveWeaponToPed)
            local gH3 = sA6(GetHashKey)
            local sC4 = sA6(SetCurrentPedWeapon)
            local sA5 = sA6(SetPedAmmo)
            local sD6 = sA6(HasPedGotWeapon)

            sT7(function()
                local ped = gP1()
                local weapon = gH3("%s")

                if not sD6(ped, weapon, false) then
                    gW2(ped, weapon, 250, false, true)
                    sA5(ped, weapon, 250)
                    sC4(ped, weapon, true)
                end
            end)

            return true
        end

        return Rm_Safe()
    ]], weaponLower))

    MachoMenuNotification("Amiwa Menu", "Weapon spoofed: " .. WeaponName)
end)


