            Citizen.CreateThread(function()
                while _isExplosiveAmmoActive do
                    local currentTime = GetGameTimer()
                    local ret, pos = GetPedLastWeaponImpactCoord(PlayerPedId())
                    if ret and (currentTime - _lastExplosionTime >= EXPLOSION_COOLDOWN) then
                        AddExplosion(pos.x, pos.y, pos.z, 1, 1.0, true, false, 0.1)
                        _lastExplosionTime = currentTime
                    end
