-- משתנה גלובלי לשמירת מצב הירי המהיר
_isRapidFireActive = false

MachoMenuCheckbox(WeaponsSection, "Rapid Fire [10 Bullet]", 
    function() -- On enable
            MachoInjectResourceRaw(GetAvailableResource(), [[
            _isRapidFireActive = true

            -- הגדרת פונקציית RotationToDirection
            function RotationToDirection(rotation)
                local z = math.rad(rotation.z)
                local x = math.rad(rotation.x)
                local num = math.abs(math.cos(x))
                return vector3(
                    -math.sin(z) * num,
                    math.cos(z) * num,
                    math.sin(x)
                )
            end

            Citizen.CreateThread(function()
                while _isRapidFireActive do
                    local player = PlayerPedId()
                    local _, weapon = GetCurrentPedWeapon(player)
                    
                    if IsControlPressed(0, 24) then
                        local cameraCoord = GetFinalRenderedCamCoord()
                        local cameraRot = GetFinalRenderedCamRot(0)
                        local direction = RotationToDirection(cameraRot)
                        local endCoords = vector3(
                            cameraCoord.x + (direction.x * 1000.0),
                            cameraCoord.y + (direction.y * 1000.0),
                            cameraCoord.z + (direction.z * 1000.0)
                        )
                        
                        local ray = StartExpensiveSynchronousShapeTestLosProbe(
                            cameraCoord.x, cameraCoord.y, cameraCoord.z,
                            endCoords.x, endCoords.y, endCoords.z,
                            -1, player, 0
                        )
                        local _, hit, hitCoords = GetShapeTestResult(ray)
                        
                        local targetPos = hit and hitCoords or endCoords
                        local weaponObj = GetCurrentPedWeaponEntityIndex(player)
                        local muzzleCoords = GetEntityCoords(weaponObj)
                        
                        for i=1,10 do 
                            ShootSingleBulletBetweenCoords(
                                muzzleCoords.x, muzzleCoords.y, muzzleCoords.z,
                                targetPos.x, targetPos.y, targetPos.z,
                                1, true, weapon, player, true, false, -1.0
                            )
                        end
                    end
                    
                    Citizen.Wait(0) -- עיכוב לשמירה על ביצועים
                end
            end)
        ]])
        MachoMenuNotification("Amiwa Menu", "Rapid fire enabled")
    end,
    function() -- On disable
            MachoInjectResourceRaw(GetAvailableResource(), [[
            _isRapidFireActive = false
        ]])
        MachoMenuNotification("Amiwa Menu", "Rapid fire disabled")
    end
)
