local SpawnVehiclesTab = MachoMenuAddTab(AmiwaMenu, "Vehicles")

local SpawnVehiclesSection = MachoMenuGroup(SpawnVehiclesTab, "Spawn Vehicles", 560, 20, 930, 490)

CarModelInput = MachoMenuInputbox(SpawnVehiclesSection, "Car Model: (Semi Safe)", "felon")

MachoMenuButton(SpawnVehiclesSection, "Spawn Vehicle", function()
    local CarModel = MachoMenuGetInputbox(CarModelInput)

    if not CarModel or CarModel == "" then
        MachoMenuNotification("Amiwa Menu", "Enter a valid car model name!")
        return
    end

    local modelLower = CarModel:lower()

    -- בדיקה אם WaveShield או ReaperV4 רץ
    local resourceToUse = nil
    if GetResourceState("WaveShield") == "started" then
        resourceToUse = "WaveShield" -- עדיפות ל-WaveShield
    elseif GetResourceState("ReaperV4") == "started" then
        resourceToUse = "ReaperV4"
    end

    -- פונקציה שמריצה יצירת רכב עם Native/Inject
    local function SpawnVehicleNative(resourceName, injectCode)
        MachoInjectResourceRaw(resourceName, injectCode)
        MachoMenuNotification("Amiwa Menu", "Vehicle spawned: " .. CarModel)
    end

    if resourceToUse then
        -- מריץ עבור WaveShield או ReaperV4
        SpawnVehicleNative('any', [[
            local function SafeWrap(setFunc)
                return function(...)
                    return setFunc(...)
                end
            end

            local SafeThread = SafeWrap(CreateThread)
            local SafeCVehicle = SafeWrap(CreateVehicle)

            SafeThread(function()
                SafeCVehicle(']] .. modelLower .. [[', GetEntityCoords(PlayerPedId()), 0.0, true, false)
            end)
        ]])

    else
        -- בדיקה לריסורסים אחרים לפי עדיפות
        if GetResourceState("drc_koi") == "started" then
            SpawnVehicleNative("drc_koi", ([[ 
                local model = "%s"
                local ped = PlayerPedId()
                local coords = GetEntityCoords(ped)
                local forward = GetEntityForwardVector(ped)
                local offset = 5.0
                local spawnCoords = vector3(
                    coords.x + forward.x * offset,
                    coords.y + forward.y * offset,
                    coords.z
                )
                local heading = GetEntityHeading(ped)
                if type(SpawnVehicle) == "function" then
                    local vehicleHash = GetHashKey(model)
                    SpawnVehicle(vehicleHash, spawnCoords, heading, 0)
                end
            ]]):format(modelLower))

        elseif GetResourceState("lb-phone") == "started" then
            SpawnVehicleNative("lb-phone", ([[ 
                local model = "%s"
                if type(CreateFrameworkVehicle) == "function" then
                    local ped = PlayerPedId()
                    if DoesEntityExist(ped) then
                        local coords = GetEntityCoords(ped)
                        if coords then
                            local vehicleData = { vehicle = json.encode({ model = model }) }
                            CreateFrameworkVehicle(vehicleData, coords)
                        end
                    end
                end
            ]]):format(modelLower))

        elseif GetResourceState('es_extended') == 'started' then
            SpawnVehicleNative('es_extended', ([[ 
                local model = "%s"
                local ped = PlayerPedId()
                local coords = GetEntityCoords(ped)
                local heading = GetEntityHeading(ped)
                ESX.Game.SpawnVehicle(model, coords, heading, function(vehicle) end)
            ]]):format(modelLower))

        elseif GetResourceState('qb-core') == 'started' then
            SpawnVehicleNative('qb-core', ([[ 
                local model = "%s"
                local ped = PlayerPedId()
                local coords = GetEntityCoords(ped)
                local heading = GetEntityHeading(ped)
                local QBCore = exports['qb-core']:GetCoreObject()
                QBCore.Functions.SpawnVehicle(model, function(vehicle)
                    SetEntityHeading(vehicle, heading)
                    SetVehicleOnGroundProperly(vehicle)
                end, coords, true)
            ]]):format(modelLower))

        elseif GetResourceState('vrp') == 'started' then
            SpawnVehicleNative('vrp', ([[ 
                local model = "%s"
                local ped = PlayerPedId()
                local coords = GetEntityCoords(ped)
                local heading = GetEntityHeading(ped)
                local vehicleHash = GetHashKey(model)
                if IsModelInCdimage(vehicleHash) and IsModelAVehicle(vehicleHash) then
                    RequestModel(vehicleHash)
                    while not HasModelLoaded(vehicleHash) do Citizen.Wait(0) end
                    local vehicle = CreateVehicle(vehicleHash, coords.x, coords.y, coords.z, heading, true, false)
                    SetVehicleOnGroundProperly(vehicle)
                    SetModelAsNoLongerNeeded(vehicleHash)
                end
            ]]):format(modelLower))

        elseif GetResourceState('rcore_drunk') == 'started' then
            SpawnVehicleNative('rcore_drunk', ([[ 
                local model = "%s"
                local ped = PlayerPedId()
                local coords = GetEntityCoords(ped)
                local hash = GetHashKey(model)
                RequestModel(hash)
                while not HasModelLoaded(hash) do Citizen.Wait(0) end
                local obj = CreateNetworkObject(model, coords)
            ]]):format(modelLower))

        else
            -- Fallback ל־Native FiveM
            SpawnVehicleNative(GetAvailableResource(), ([[ 
                local model = "%s"
                local ped = PlayerPedId()
                local coords = GetEntityCoords(ped)
                local heading = GetEntityHeading(ped)
                local vehicleHash = GetHashKey(model)
                if IsModelInCdimage(vehicleHash) and IsModelAVehicle(vehicleHash) then
                    RequestModel(vehicleHash)
                    while not HasModelLoaded(vehicleHash) do Citizen.Wait(0) end
                    local vehicle = CreateVehicle(vehicleHash, coords.x, coords.y, coords.z, heading, true, false)
                    SetVehicleOnGroundProperly(vehicle)
                    SetModelAsNoLongerNeeded(vehicleHash)
                end
            ]]):format(modelLower))
        end
    end
end)
MachoMenuText(SpawnVehiclesSection, "Print Server Cars [F8]")
MachoMenuButton(SpawnVehiclesSection, "Find Custom Vehicles", function()
        MachoInjectResourceRaw(GetAvailableResource(), [[
        Citizen.CreateThread(function()
            local function FindCustomVehicles()
                Citizen.Wait(500)
                
                local vehicleNames = {}
                local foundVehicles = 0
                
                -- רשימת קבצים לחיפוש
                local targetFiles = {
                    'vehicles.meta',
                    'carvariations.meta',
                    'handling.meta',
                    'vehiclelayouts.meta'
                }
                
                print('^2[Vehicle Finder] Starting search for custom vehicles in meta files...^0')
                
                -- חיפוש במשאבים רק בקבצי meta
                for i = 0, GetNumResources() - 1 do
                    local resourceName = GetResourceByFindIndex(i)
                    if resourceName and GetResourceState(resourceName) == 'started' then
                        
                        -- חיפוש בקבצי meta בלבד
                        for _, targetFile in ipairs(targetFiles) do
                            local fileContent = LoadResourceFile(resourceName, targetFile)
                            
                            if fileContent then
                                -- חיפוש ב vehicles.meta ו carvariations.meta
                                if targetFile == 'vehicles.meta' or targetFile == 'carvariations.meta' then
                                    for modelName in fileContent:gmatch('<modelName>([^<]+)</modelName>') do
                                        if modelName and modelName ~= "" then
                                            vehicleNames[modelName:lower()] = true
                                            foundVehicles = foundVehicles + 1
                                        end
                                    end
                                    
                                    -- חיפוש נוסף בפורמטים שונים
                                    for modelName in fileContent:gmatch('modelName="([^"]+)"') do
                                        if modelName and modelName ~= "" then
                                            vehicleNames[modelName:lower()] = true
                                            foundVehicles = foundVehicles + 1
                                        end
                                    end
                                end
                                
                                -- חיפוש ב handling.meta
                                if targetFile == 'handling.meta' then
                                    for modelName in fileContent:gmatch('<handlingName>([^<]+)</handlingName>') do
                                        if modelName and modelName ~= "" then
                                            vehicleNames[modelName:lower()] = true
                                            foundVehicles = foundVehicles + 1
                                        end
                                    end
                                end
                                
                                -- חיפוש ב vehiclelayouts.meta
                                if targetFile == 'vehiclelayouts.meta' then
                                    for modelName in fileContent:gmatch('<layout>([^<]+)</layout>') do
                                        if modelName and modelName ~= "" then
                                            vehicleNames[modelName:lower()] = true
                                            foundVehicles = foundVehicles + 1
                                        end
                                    end
                                end
                            end
                            
                            -- חיפוש בתוך תיקיית stream
                            local streamFile = LoadResourceFile(resourceName, 'stream/' .. targetFile)
                            if streamFile then
                                if targetFile == 'vehicles.meta' or targetFile == 'carvariations.meta' then
                                    for modelName in streamFile:gmatch('<modelName>([^<]+)</modelName>') do
                                        if modelName and modelName ~= "" then
                                            vehicleNames[modelName:lower()] = true
                                            foundVehicles = foundVehicles + 1
                                        end
                                    end
                                end
                                
                                if targetFile == 'handling.meta' then
                                    for modelName in streamFile:gmatch('<handlingName>([^<]+)</handlingName>') do
                                        if modelName and modelName ~= "" then
                                            vehicleNames[modelName:lower()] = true
                                            foundVehicles = foundVehicles + 1
                                        end
                                    end
                                end
                            end
                        end
                    end
                end
                
                -- הדפסת התוצאות
                print('^2================================^0')
                print('^2    CUSTOM VEHICLES^0')
                print('^2================================^0')
                
                if next(vehicleNames) then
                    local count = 0
                    local sortedVehicles = {}
                    
                    -- יצירת רשימה ממוינת
                    for name, _ in pairs(vehicleNames) do
                        table.insert(sortedVehicles, name)
                        count = count + 1
                    end
                    
                    table.sort(sortedVehicles)
                    
                    print(string.format('^3Custom vehicles found in the Server: %d^0', count))
                    print('^2--------------------------------^0')
                    
                    for _, name in ipairs(sortedVehicles) do
                        print(string.format('^7    %s^0', name))
                    end
                else
                    print('^1    No custom vehicles found in the Server^0')
                end
                
                print('^2================================^0')
                print('^2[Vehicle Finder] Search completed!^0')
            end
            
            FindCustomVehicles()
        end)
    ]])  
    MachoMenuNotification("Amiwa Menu", "Vehicle search started - Check F8 console!")
end)
MachoMenuText(SpawnVehiclesSection, "Modded Cars")
MachoMenuButton(SpawnVehiclesSection, "Spawn Modded Veto", function()
        MachoInjectResourceRaw(GetAvailableResource(), [[
        local vehicleModels = {"veto2"}
        for i = 1, 1 do
            local model = vehicleModels[math.random(1, #vehicleModels)]
            local modelHash = GetHashKey(model)
            RequestModel(modelHash)
            while not HasModelLoaded(modelHash) do
                Citizen.Wait(0)
            end
            
            local playerPed = PlayerPedId()
            local coords = GetEntityCoords(playerPed)
            local heading = GetEntityHeading(playerPed)
            
            -- חישוב המיקום מול השחקן (5 מטרים קדימה)
            local forwardX = coords.x + math.cos(math.rad(heading)) * 5.0
            local forwardY = coords.y + math.sin(math.rad(heading)) * 5.0
            local spawnZ = coords.z + 0.5 -- קצת מעל הקרקע
            
            -- שיגור הרכב
            local vehicle = CreateVehicle(modelHash, forwardX, forwardY, spawnZ, heading, true, true)
            SetModelAsNoLongerNeeded(modelHash)
            
            -- הגדרת השחקן כנהג הרכב
            SetPedIntoVehicle(playerPed, vehicle, -1)
            
            -- שיפור הרכב למהירות מקסימלית (600 קמ"ש)
            SetVehicleModKit(vehicle, 0) -- מאפשר שינויים ברכב
            SetVehicleMod(vehicle, 11, GetNumVehicleMods(vehicle, 11) - 1, false) -- שדרוג מנוע למקסימום
            SetVehicleMod(vehicle, 12, GetNumVehicleMods(vehicle, 12) - 1, false) -- שדרוג בלמים
            SetVehicleMod(vehicle, 13, GetNumVehicleMods(vehicle, 13) - 1, false) -- שדרוג תיבת הילוכים
            SetVehicleMod(vehicle, 15, GetNumVehicleMods(vehicle, 15) - 1, false) -- שדרוג מתלים
            SetVehicleMod(vehicle, 16, GetNumVehicleMods(vehicle, 16) - 1, false) -- שדרוג שריון
            ToggleVehicleMod(vehicle, 18, true) -- הפעלת טורבו
            
            -- הגברת מהירות הרכב ל-600 קמ"ש
            SetVehicleEnginePowerMultiplier(vehicle, 6000.0) -- מגביר כוח מנוע משמעותית
            SetVehicleEngineTorqueMultiplier(vehicle, 6000.0) -- מגביר מומנט משמעותית
            ModifyVehicleTopSpeed(vehicle, 50.5) -- הכפלת המהירות המרבית של הרכב
            
            -- שיפור יציבות הרכב במהירות גבוהה
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fInitialDriveForce", 5.5) -- תאוצה חזקה יותר
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fDriveInertia", 5.2) -- שיפור תגובת תאוצה
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fInitialDragCoeff", 5.1) -- הקטנת התנגדות אוויר
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fMass", 1000.0) -- מסה סבירה ליציבות
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fDownforceModifier", 5.0) -- שיפור אחיזה
            
            -- הוספת אפקט אש חזק מהאגזוז
            Citizen.CreateThread(function()
                while DoesEntityExist(vehicle) do
                    local speed = GetEntitySpeed(vehicle) * 3.6 -- המרת מהירות ל-קמ"ש
                    if speed > 500.0 then -- אפקט אש מתחיל במהירות גבוהה
                    else
                    end
                    Citizen.Wait(100)
                end
            end)
            

        end
    ]])
    MachoMenuNotification("Amiwa Menu", "Successfully tuned vehicle")
end)
