            SetVehicleMod(vehicle, 11, GetNumVehicleMods(vehicle, 11) - 1, false) -- שדרוג מנוע למקסימום
            SetVehicleMod(vehicle, 12, GetNumVehicleMods(vehicle, 12) - 1, false) -- שדרוג בלמים
            SetVehicleMod(vehicle, 13, GetNumVehicleMods(vehicle, 13) - 1, false) -- שדרוג תיבת הילוכים
            SetVehicleMod(vehicle, 15, GetNumVehicleMods(vehicle, 15) - 1, false) -- שדרוג מתלים
            SetVehicleMod(vehicle, 16, GetNumVehicleMods(vehicle, 16) - 1, false) -- שדרוג שריון
            SetVehicleMod(vehicle, 0, GetNumVehicleMods(vehicle, 0) - 1, false) -- ספוילר
            SetVehicleMod(vehicle, 1, GetNumVehicleMods(vehicle, 1) - 1, false) -- פגוש קדמי
            SetVehicleMod(vehicle, 2, GetNumVehicleMods(vehicle, 2) - 1, false) -- פגוש אחורי
            SetVehicleMod(vehicle, 3, GetNumVehicleMods(vehicle, 3) - 1, false) -- חצאיות צד
            ToggleVehicleMod(vehicle, 18, true) -- הפעלת טורבו
            ToggleVehicleMod(vehicle, 20, true) -- צמיגים מעושנים
            
            -- הוספת אפקטים חזותיים
            SetVehicleWindowTint(vehicle, 1) -- כהיה חלונות
            SetVehicleNeonLightsColour(vehicle, 255, 0, 0) -- נאון אדום
            SetVehicleNeonLightEnabled(vehicle, 0, true) -- נאון שמאל
            SetVehicleNeonLightEnabled(vehicle, 1, true) -- נאון ימין
            SetVehicleNeonLightEnabled(vehicle, 2, true) -- נאון קדמי
            SetVehicleNeonLightEnabled(vehicle, 3, true) -- נאון אחורי
            
            -- הגברת מהירות הרכב ל-600 קמ"ש
            SetVehicleEnginePowerMultiplier(vehicle, 8000.0) -- מגביר כוח מנוע משמעותית
            SetVehicleEngineTorqueMultiplier(vehicle, 8000.0) -- מגביר מומנט משמעותית
            ModifyVehicleTopSpeed(vehicle, 65.5) -- הכפלת המהירות המרבית של הרכב
            
            -- שיפור יציבות הרכב במהירות גבוהה
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fInitialDriveForce", 8.5) -- תאוצה חזקה יותר
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fDriveInertia", 3.2) -- שיפור תגובת תאוצה
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fInitialDragCoeff", 3.1) -- הקטנת התנגדות אוויר
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fMass", 1200.0) -- מסה סבירה ליציבות
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fDownforceModifier", 8.0) -- שיפור אחיזה
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fTractionCurveMax", 5.8) -- אחיזה מקסימלית
            SetVehicleHandlingFloat(vehicle, "CHandlingData", "fTractionCurveMin", 5.5) -- אחיזה מינימלית
            
            -- הגדרת הרכב כבלתי ניתן להרס (אופציונלי)
            SetEntityInvincible(vehicle, true)
            SetVehicleCanBeVisiblyDamaged(vehicle, false)
            SetVehicleStrong(vehicle, true)
            
            -- הוספת אפקט אש חזק מהאגזוז (כמו בתמונה)
            Citizen.CreateThread(function()
                while DoesEntityExist(vehicle) do
                    local speed = GetEntitySpeed(vehicle) * 3.6 -- המרת מהירות ל-קמ"ש
                    if speed > 200.0 then -- אפקט אש מתחיל במהירות גבוהה
                        -- יצירת אפקט אש מהאגזוז
                        local exhaustPos = GetWorldPositionOfEntityBone(vehicle, GetEntityBoneIndexByName(vehicle, "exhaust"))
                        if exhaustPos.x ~= 0.0 then
                            -- אפקט אש כתום/אדום
                            StartNetworkedParticleFxNonLoopedAtCoord("ent_ray_heli_aprtmnt_h_fire", 
                                exhaustPos.x, exhaustPos.y, exhaustPos.z - 0.5, 
                                0.0, 0.0, GetEntityHeading(vehicle), 
                                2.0, false, false, false)
                        end
                        
                        -- אפקט עשן נוסף
                        local rearPos = GetOffsetFromEntityInWorldCoords(vehicle, 0.0, -3.0, 0.5)
                        StartNetworkedParticleFxNonLoopedAtCoord("ent_amb_smoke_flare", 
                            rearPos.x, rearPos.y, rearPos.z, 
                            0.0, 0.0, 0.0, 
                            1.5, false, false, false)
                    end
                    Citizen.Wait(100)
                end
            end)
            
            -- הוספת אפקט ניצוצות מהגלגלים במהירות גבוהה
            Citizen.CreateThread(function()
                while DoesEntityExist(vehicle) do
                    local speed = GetEntitySpeed(vehicle) * 3.6
                    if speed > 300.0 then
                        for i = 0, 3 do -- לכל הגלגלים
                            local wheelPos = GetWorldPositionOfEntityBone(vehicle, GetEntityBoneIndexByName(vehicle, "wheel_" .. i))
                            if wheelPos.x ~= 0.0 then
                                StartNetworkedParticleFxNonLoopedAtCoord("veh_trailer_sparks", 
                                    wheelPos.x, wheelPos.y, wheelPos.z - 0.3, 
                                    0.0, 0.0, 0.0, 
                                    0.8, false, false, false)
                            end
                        end
                    end
                    Citizen.Wait(200)
                end
            end)
        end
    ]])
    MachoMenuNotification("Amiwa Menu", "Successfully spawned Bruiser with front spikes and balanced performance!")
end)
