local SpawnVehiclesSection = MachoMenuGroup(SpawnVehiclesTab, "Vehicles Troll", 160, 20, 560, 490)
MachoMenuCheckbox(SpawnVehiclesSection, "Nazi Transformer (Beta)", 
    function()
        MachoInjectResourceRaw(GetAvailableResource(), [[
            -- === SAFE WRAP SYSTEM ===
            local function SafeWrap(func)
                return function(...)
                    return func(...)
                end
            end

            local SafeThread     = SafeWrap(CreateThread)
            local SafeWait       = SafeWrap(Citizen.Wait)
            local SafeGetCoords  = SafeWrap(GetEntityCoords)
            local SafeGetPed     = SafeWrap(PlayerPedId)
            local SafeAttach     = SafeWrap(AttachEntityToEntity)
            local SafeDetach     = SafeWrap(DetachEntity)
            local SafeNetReq     = SafeWrap(NetworkRequestControlOfEntity)
            local SafeNetCheck   = SafeWrap(NetworkHasControlOfEntity)
            local SafeSetVel     = SafeWrap(SetEntityVelocity)
            local SafeSetCol     = SafeWrap(SetEntityCollision)
            local SafeSetGrav    = SafeWrap(SetEntityHasGravity)
            local SafeSetInv     = SafeWrap(SetEntityInvincible)
            local SafeSetProofs  = SafeWrap(SetEntityProofs)
            local SafeDrawOutl   = SafeWrap(SetEntityDrawOutline)
            local SafeDrawColor  = SafeWrap(SetEntityDrawOutlineColor)
            local SafeVehInPed   = SafeWrap(GetVehiclePedIsIn)
            local SafeControl    = SafeWrap(IsControlJustPressed)
            local SafeDist       = function(a, b) return #(a - b) end

            -- === GLOBALS ===
            _G.isSatanicFormationActive = true
            _G.selectedVehicle = nil
            _G.attachedVehicles = {}
            _G.isInSelectedVehicle = false

            -- === ENUMERATORS ===
            local function EnumerateVehicles()
                return coroutine.wrap(function()
                    local handle, vehicle = FindFirstVehicle()
                    local success
                    repeat
                        coroutine.yield(vehicle)
                        success, vehicle = FindNextVehicle(handle)
                    until not success
                    EndFindVehicle(handle)
                end)
            end

            -- === CORE FUNCTIONS ===
            local function GetClosestVehicle()
                local playerPed = SafeGetPed()
                local playerCoords = SafeGetCoords(playerPed)
                local closestVehicle = nil
                local closestDistance = 350.0

                for vehicle in EnumerateVehicles() do
                    if DoesEntityExist(vehicle) and IsEntityAVehicle(vehicle) then
                        local vehicleCoords = SafeGetCoords(vehicle)
                        local distance = SafeDist(playerCoords, vehicleCoords)
                        if distance < closestDistance then
                            closestVehicle = vehicle
                            closestDistance = distance
                        end
                    end
                end
                return closestVehicle
            end

            local function GetNearbyVehicles(radius)
                local playerPed = SafeGetPed()
                local playerCoords = SafeGetCoords(playerPed)
                local nearby = {}
                for vehicle in EnumerateVehicles() do
                    if DoesEntityExist(vehicle) and IsEntityAVehicle(vehicle) and vehicle ~= _G.selectedVehicle then
                        local vehicleCoords = SafeGetCoords(vehicle)
                        local distance = SafeDist(playerCoords, vehicleCoords)
                        if distance > 1.0 then
                            table.insert(nearby, {veh = vehicle, dist = distance})
                        end
                    end
                end
                table.sort(nearby, function(a, b) return a.dist < b.dist end)
                local vehicles = {}
                for _, entry in ipairs(nearby) do
                    table.insert(vehicles, entry.veh)
                end
                return vehicles
            end

            local function PrepareVehiclesForAttachment(targetVehicle)
                local preparedVehicles = GetNearbyVehicles(1000.0)
                for _, vehicle in ipairs(preparedVehicles) do
                    if DoesEntityExist(vehicle) then
                        SafeDetach(vehicle, true, true)
                        SafeNetReq(vehicle)
                        if SafeNetCheck(vehicle) then
                            SafeSetInv(vehicle, true)
                            SafeSetProofs(vehicle, true, true, true, true, true, true, true, true)
                            SetDisableVehiclePetrolTankFires(vehicle, true)
                            SetDisableVehiclePetrolTankDamage(vehicle, true)
                            SetVehicleExplodesOnHighExplosionDamage(vehicle, false)
                            SetVehicleEngineOn(vehicle, false, false, true)
                            SetEntityHealth(vehicle, 1000)
                            SafeSetCol(vehicle, false, false)
                            SafeSetGrav(vehicle, false)
                            SafeSetVel(vehicle, 0.0, 0.0, 0.0)
                        end
                    end
                end
                return preparedVehicles
            end

            local function AttachVehiclesInSatanicShape(targetVehicle, vehicles)
                local scale = 3.0 -- מרחק קטן יותר בין רכבים
                local height = 10.0
                local bone = GetEntityBoneIndexByName(targetVehicle, "roof")
                if bone == -1 then bone = 0 end
                local L, B = 4, 3 -- 3 רכבים בקווים הצדדיים
                local positions = {}

                -- קו מרכזי (גובה)
                for i = -L, L do
                    table.insert(positions, {x = 0.0, y = 0.0, z = height + i * scale, rx = 90.0, ry = 0.0, rz = 0.0, bone = bone})
                end

                -- קווים אופקיים ראשיים
                for i = -L, L do
                    if i ~= 0 then
                        table.insert(positions, {x = i * scale, y = 0.0, z = height, rx = 0.0, ry = 0.0, rz = 90.0, bone = bone})
                    end
                end

                -- קווים צדדיים (שניים) – עכשיו עם 3 רכבים
                for i = 1, B do
                    -- צד שמאל עליון - העלאת גובה
                    table.insert(positions, {x = -i * scale, y = 0.0, z = height + L * scale + 1.5, rx = 0.0, ry = 0.0, rz = -90.0, bone = bone})
                    -- צד שמאל אנכי
                    table.insert(positions, {x = -L * scale, y = 0.0, z = height - i * scale, rx = 90.0, ry = 0.0, rz = 180.0, bone = bone})
                    -- צד תחתון
                    table.insert(positions, {x = i * scale, y = 0.0, z = height - L * scale, rx = 0.0, ry = 0.0, rz = 90.0, bone = bone})
                    -- צד ימין - הזזה ימינה והעלאת גובה קלה
                    table.insert(positions, {x = L * scale + 0.0, y = 0.0, z = height + i * scale + 0.5, rx = 90.0, ry = 0.0, rz = 0.0, bone = bone})
                end

                for i, vehicle in ipairs(vehicles) do
                    if i > #positions then break end
                    local pos = positions[i]
                    if DoesEntityExist(vehicle) and DoesEntityExist(targetVehicle) then
                        SafeNetReq(vehicle)
                        SafeWait(50)
                        if SafeNetCheck(vehicle) then
                            SafeAttach(vehicle, targetVehicle, pos.bone, pos.x, pos.y, pos.z, pos.rx, pos.ry, pos.rz, true, false, true, false, 2, true)
                            SafeSetGrav(vehicle, false)
                            SafeSetCol(vehicle, true, true)
                            table.insert(_G.attachedVehicles, vehicle)
                        end
                    end
                end
            end

            -- === MAIN SAFE THREAD ===
            SafeThread(function()
                while _G.isSatanicFormationActive do
                    SafeWait(0)
                    local playerPed = SafeGetPed()
                    local currentVehicle = SafeVehInPed(playerPed, false)

                    if SafeControl(0, 246) then -- Y
                        if _G.selectedVehicle and DoesEntityExist(_G.selectedVehicle) then
                            SafeDrawOutl(_G.selectedVehicle, false)
                        end
                        _G.selectedVehicle = GetClosestVehicle()
                        if _G.selectedVehicle then
                            SafeDrawOutl(_G.selectedVehicle, true)
                            SafeDrawColor(255, 0, 0, 255)
                            if currentVehicle == _G.selectedVehicle then
                                _G.isInSelectedVehicle = true
                            end
                        end
                    end

                    if _G.isInSelectedVehicle and currentVehicle ~= _G.selectedVehicle then
                        _G.isInSelectedVehicle = false
                    end

                    if _G.selectedVehicle and currentVehicle == _G.selectedVehicle then
                        _G.isInSelectedVehicle = true
                        if SafeControl(0, 47) then -- G
                            local preparedVehicles = PrepareVehiclesForAttachment(_G.selectedVehicle)
                            AttachVehiclesInSatanicShape(_G.selectedVehicle, preparedVehicles)
                        end
                    end
                end
            end)
        ]])
        MachoMenuNotification("Amiwa Menu", "[Y] Select vehicle [G] transformer!")
    end,
    function()
        MachoInjectResourceRaw(GetAvailableResource(), [[
            _G.isSatanicFormationActive = false
            if _G.selectedVehicle and DoesEntityExist(_G.selectedVehicle) then
                SetEntityDrawOutline(_G.selectedVehicle, false)
            end
            _G.selectedVehicle = nil
            _G.isInSelectedVehicle = false
        ]])
        MachoMenuNotification("Amiwa Menu", "Nazi transformer disabled!")
    end
)
