                if closestVehicle then

                else

                end
                return closestVehicle
            end

            function EnumerateVehicles()
                return coroutine.wrap(function()
                    local handle, vehicle = FindFirstVehicle()
                    local success
                    repeat
                        coroutine.yield(vehicle)
                        success, vehicle = FindNextVehicle(handle)
                    until not success
                    EndFindVehicle(handle)
                end)
            end

            function GetCoordsInFrontOfCam(coords, distance)
                local rotation = GetGameplayCamRot(2)
                local direction = RotationToDirection(rotation)
                return {
                    x = coords.x + direction.x * distance,
                    y = coords.y + direction.y * distance,
                    z = coords.z + direction.z * distance
                }
            end

            function RotationToDirection(rotation)
                local radians = rotation * (math.pi / 180.0)
                return {
                    x = -math.sin(radians.z) * math.abs(math.cos(radians.x)),
                    y = math.cos(radians.z) * math.abs(math.cos(radians.x)),
                    z = math.sin(radians.x)
                }
            end

            Citizen.CreateThread(function()
                while _G.isVehicleFlyActive do
                    Citizen.Wait(0)

                    -- בחירת רכב עם Y
                    if IsControlJustPressed(0, 246) then -- Y key
                        if _G.selectedVehicle and DoesEntityExist(_G.selectedVehicle) then
                            SetEntityDrawOutline(_G.selectedVehicle, false)
                        end
                        _G.selectedVehicle = GetClosestVehicle()
                        if _G.selectedVehicle then
                            SetEntityDrawOutline(_G.selectedVehicle, true)
                            SetEntityDrawOutlineColor(255, 255, 0, 255)
                        end
                    end

                    -- שליטה במרחק עם גלגלת
                    if _G.selectedVehicle and DoesEntityExist(_G.selectedVehicle) then
                        -- גלגלת למעלה (התקרבות)
                        if IsControlJustPressed(0, 16) then -- Mouse Wheel Up
                            _G.distanceOffset = math.max(_G.distanceOffset - 10.0, 1.0)
                        end
                        -- גלגלת למטה (התרחקות)
                        if IsControlJustPressed(0, 17) then -- Mouse Wheel Down
                            _G.distanceOffset = _G.distanceOffset + 10.0 -- ללא מגבלה עליון
                        end

                        -- הזזת הרכב עם E
                        if IsControlPressed(0, 38) then -- E key
                            if not _G.isVehicleFlying then
                                _G.isVehicleFlying = true
                                SetEntityHasGravity(_G.selectedVehicle, false)
                                SetEntityCollision(_G.selectedVehicle, false, false)
                            end

                            local playerCoords = GetEntityCoords(PlayerPedId())
                            local camRot = GetGameplayCamRot(2)
                            local targetCoords = GetCoordsInFrontOfCam(playerCoords, _G.distanceOffset)

                            -- הזזת הרכב לכיוון המצלמה
                            SetEntityCoords(_G.selectedVehicle, 
                                targetCoords.x, 
                                targetCoords.y, 
                                targetCoords.z, 
                                false, false, false, true
                            )
                            -- סיבוב הרכב לפי כיוון המצלמה
                            SetEntityRotation(_G.selectedVehicle, camRot.x, camRot.y, camRot.z, 2, true)
                        else
                            if _G.isVehicleFlying then
                                _G.isVehicleFlying = false
                                SetEntityHasGravity(_G.selectedVehicle, true)
                                SetEntityCollision(_G.selectedVehicle, true, true)

                                -- בדיקה אם השחקן מחוץ לרכב, ואז הטלת הרכב קדימה במהירות חזקה
                                local playerPed = PlayerPedId()
                                local currentVehicle = GetVehiclePedIsIn(playerPed, false)
                                if currentVehicle ~= _G.selectedVehicle then
                                    local camRot = GetGameplayCamRot(2)
                                    local dirX = -math.sin(math.rad(camRot.z)) * math.abs(math.cos(math.rad(camRot.x)))
                                    local dirY = math.cos(math.rad(camRot.z)) * math.abs(math.cos(math.rad(camRot.x)))
                                    local dirZ = math.sin(math.rad(camRot.x))
                                    local propulsionSpeed = 500.0  -- מהירות הטלה חזקה מאוד
                                    SetEntityVelocity(_G.selectedVehicle, 
                                        dirX * propulsionSpeed, 
                                        dirY * propulsionSpeed, 
                                        dirZ * propulsionSpeed
                                    )

                                else

                                end
                            end
                        end
                    end
                end
            end)
        ]])
         MachoMenuNotification("Amiwa Menu", "[Y] Select [E] Comtrol!")
    end,
    function()
