MachoMenuCheckbox(SpawnVehiclesSection, "Pickup Vehicles", function()
    MachoInjectResourceRaw('monitor', [[
        if AmiwaPickupCars == nil then AmiwaPickupCars = false end
        AmiwaPickupCars = true

        local holdingCarEntity = false
        local heldEntity = nil

        CreateThread(function()
            while AmiwaPickupCars and not Unloaded do
                Wait(0)
                local playerPed = PlayerPedId()
                local camPos = GetGameplayCamCoord()
                local camRot = GetGameplayCamRot(2)
                local direction = RotationToDirection(camRot)
                local dest = vec3(camPos.x + direction.x * 10.0, camPos.y + direction.y * 10.0, camPos.z + direction.z * 10.0)

                -- מחפש אך ורק רכבים (entityType == 2)
                local rayHandle = StartShapeTestRay(camPos.x, camPos.y, camPos.z, dest.x, dest.y, dest.z, 2, playerPed, 0)
                local _, hit, _, _, entityHit = GetShapeTestResult(rayHandle)

                if IsControlJustReleased(0, 246) then -- Y key
                    if not holdingCarEntity then
                        if hit == 1 and entityHit and GetEntityType(entityHit) == 2 then
                            -- מבקש שליטה ברכב
                            NetworkRequestControlOfEntity(entityHit)
                            local timeout = GetGameTimer() + 2000
                            while not NetworkHasControlOfEntity(entityHit) and GetGameTimer() < timeout do
                                Wait(10)
                                NetworkRequestControlOfEntity(entityHit)
                            end

                            if NetworkHasControlOfEntity(entityHit) then
                                holdingCarEntity = true
                                heldEntity = entityHit
                                AttachEntityToEntity(heldEntity, playerPed, GetPedBoneIndex(playerPed, 60309),
                                    1.0, 0.5, 0.0, 0.0, 0.0, 0.0,
                                    true, true, false, false, 1, true)

                                RequestAnimDict('anim@mp_rollarcoaster')
                                while not HasAnimDictLoaded('anim@mp_rollarcoaster') do Wait(100) end
                                TaskPlayAnim(playerPed, 'anim@mp_rollarcoaster', 'hands_up_idle_a_player_one',
                                    8.0, -8.0, -1, 50, 0, false, false, false)
                            end
                        end
                    else
                        DetachEntity(heldEntity, true, true)
                        ApplyForceToEntity(heldEntity, 1,
                            direction.x * 500, direction.y * 500, direction.z * 500,
                            0.0, 0.0, 0.0, 0, false, true, true, false, true)
                        holdingCarEntity = false
                        heldEntity = nil
                        ClearPedTasks(playerPed)
                    end
                end
            end
        end)

        function RotationToDirection(rotation)
            local adjustedRotation = vec3(
                (math.pi / 180) * rotation.x,
                (math.pi / 180) * rotation.y,
                (math.pi / 180) * rotation.z
            )
            local direction = vec3(
                -math.sin(adjustedRotation.z) * math.abs(math.cos(adjustedRotation.x)),
                math.cos(adjustedRotation.z) * math.abs(math.cos(adjustedRotation.x)),
                math.sin(adjustedRotation.x)
            )
            return direction
        end
    ]])
    MachoMenuNotification("Amiwa Menu", "Use [Y] To Pickup Vehicles")
