MachoMenuCheckbox(SpawnVehiclesSection, "Jump Car", 
    function()
            MachoInjectResourceRaw(GetAvailableResource(), [[
            _G.isJumpCarEnabled = true
            _G.jumpForce = 15.0 -- עוצמת הקפיצה
            _G.jumpCooldown = 0 -- זמן המתנה בין קפיצות
            _G.maxJumpCooldown = 500 -- 500ms בין קפיצות
            
            Citizen.CreateThread(function()
                while _G.isJumpCarEnabled do
                    Citizen.Wait(0)
                    local playerPed = PlayerPedId()
                    
                    if not playerPed or not DoesEntityExist(playerPed) then
                        return
                    end
                    
                    if IsPedInAnyVehicle(playerPed, false) then
                        local vehicle = GetVehiclePedIsIn(playerPed, false)
                        
                        if vehicle and DoesEntityExist(vehicle) then
                            local currentTime = GetGameTimer()
                            
                            -- בדיקה אם SPACE נלחץ וזמן המתנה עבר
                            if IsControlJustPressed(0, 22) and currentTime > _G.jumpCooldown then -- Space key
                                -- קפיצה מגניבה למעלה!
                                local velocity = GetEntityVelocity(vehicle)
                                
                                -- שמירה על המהירות הנוכחית בצירים X,Y ויצירת קפיצה חזקה בציר Z
                                SetEntityVelocity(vehicle, velocity.x, velocity.y, _G.jumpForce)
                                
                                -- אפקט נוסף - דחיפה קלה קדימה כדי שזה יראה יותר דינמי
                                local forwardVector = GetEntityForwardVector(vehicle)
                                ApplyForceToEntity(vehicle, 1, 
                                    forwardVector.x * 2.0, 
                                    forwardVector.y * 2.0, 
                                    0.0, 
                                    0.0, 0.0, 0.0, 
                                    false, true, true, false, false, true
                                )
                                
                                -- הגדרת זמן המתנה הבא
                                _G.jumpCooldown = currentTime + _G.maxJumpCooldown
                                
                                -- הודעה חזותית (אופציונלי)
                            end
                            
                            -- שיפור יציבות נחיתה - מפחית זעזועים חזקים
                            local vehicleVelocity = GetEntityVelocity(vehicle)
                            if vehicleVelocity.z < -20.0 then -- נופל מהר מאוד
                                -- הפחתת מהירות נפילה בהדרגה כדי שהנחיתה תהיה רכה יותר
                                SetEntityVelocity(vehicle, vehicleVelocity.x, vehicleVelocity.y, vehicleVelocity.z * 0.95)
                            end
                        end
                    end
                end
                
                -- ניקוי כשהפיצ'ר מכובה
            end)
        ]], false)
        MachoMenuNotification("Amiwa Menu", "Jump car enabled press SPACE to jump!")
    end,
    function()
            MachoInjectResourceRaw(GetAvailableResource(), [[
            _G.isJumpCarEnabled = false
            _G.jumpCooldown = 0
            
            -- ניקוי מיידי של משתנים
            local playerPed = PlayerPedId()
            if IsPedInAnyVehicle(playerPed, false) then
                local vehicle = GetVehiclePedIsIn(playerPed, false)
                if vehicle and DoesEntityExist(vehicle) then
