                    end
                end
            end
        ]], false)
        MachoMenuNotification("Amiwa Menu", "Jump car disabled")
    end
)
MachoMenuCheckbox(SpawnVehiclesSection, "Vehicle Collision", 
    function()
        _G.isAntiVDMEnabled = true

        MachoInjectResourceRaw(GetAvailableResource(), [[
            local function SafeWrap(fn)
                return function(...)
                    return fn(...)
                end
            end

            local SafeThread = SafeWrap(CreateThread)
            local SafePlayerPedId = SafeWrap(PlayerPedId)
            local SafeDoesEntityExist = SafeWrap(DoesEntityExist)
            local SafeIsPedInAnyVehicle = SafeWrap(IsPedInAnyVehicle)
            local SafeGetVehiclePedIsIn = SafeWrap(GetVehiclePedIsIn)
            local SafeSetEntityNoCollisionEntity = SafeWrap(SetEntityNoCollisionEntity)
            local SafeGetGamePool = SafeWrap(GetGamePool)
            local SafeSetVehicleCanBeVisiblyDamaged = SafeWrap(SetVehicleCanBeVisiblyDamaged)
            local SafeSetVehicleStrong = SafeWrap(SetVehicleStrong)
            local SafeWait = SafeWrap(Citizen.Wait)

            local function disableVehicleCollisions()
                local playerPed = SafePlayerPedId()
                if not SafeDoesEntityExist(playerPed) then return end

                if SafeIsPedInAnyVehicle(playerPed, false) then
                    local vehicle = SafeGetVehiclePedIsIn(playerPed, false)
                    if vehicle and SafeDoesEntityExist(vehicle) then
                        SafeSetEntityNoCollisionEntity(vehicle, vehicle, false)
                        local nearbyVehicles = SafeGetGamePool('CVehicle')
                        for _, otherVehicle in ipairs(nearbyVehicles) do
                            if otherVehicle ~= vehicle then
                                SafeSetEntityNoCollisionEntity(vehicle, otherVehicle, true)
                                SafeSetEntityNoCollisionEntity(otherVehicle, vehicle, true)
                            end
                        end
                        SafeSetVehicleCanBeVisiblyDamaged(vehicle, false)
                        SafeSetVehicleStrong(vehicle, true)
                    end
                end
            end

            SafeThread(function()
                while _G.isAntiVDMEnabled do
                    disableVehicleCollisions()
                    SafeWait(0)
                end
            end)
        ]])

        MachoMenuNotification("Amiwa Menu", "Vehicle - collision enabled!")
    end,

    function()
        _G.isAntiVDMEnabled = false

        MachoInjectResourceRaw(GetAvailableResource(), [[
            local function SafeWrap(fn)
                return function(...)
                    return fn(...)
                end
            end

            local SafeThread = SafeWrap(CreateThread)
            local SafePlayerPedId = SafeWrap(PlayerPedId)
            local SafeDoesEntityExist = SafeWrap(DoesEntityExist)
            local SafeIsPedInAnyVehicle = SafeWrap(IsPedInAnyVehicle)
            local SafeGetVehiclePedIsIn = SafeWrap(GetVehiclePedIsIn)
            local SafeSetEntityNoCollisionEntity = SafeWrap(SetEntityNoCollisionEntity)
            local SafeGetGamePool = SafeWrap(GetGamePool)
            local SafeSetVehicleCanBeVisiblyDamaged = SafeWrap(SetVehicleCanBeVisiblyDamaged)
            local SafeSetVehicleStrong = SafeWrap(SetVehicleStrong)

            local function restoreVehicleCollisions()
                local playerPed = SafePlayerPedId()
                if SafeIsPedInAnyVehicle(playerPed, false) then
                    local vehicle = SafeGetVehiclePedIsIn(playerPed, false)
                    if vehicle and SafeDoesEntityExist(vehicle) then
                        local nearbyVehicles = SafeGetGamePool('CVehicle')
                        for _, otherVehicle in ipairs(nearbyVehicles) do
                            if otherVehicle ~= vehicle then
                                SafeSetEntityNoCollisionEntity(vehicle, otherVehicle, false)
                                SafeSetEntityNoCollisionEntity(otherVehicle, vehicle, false)
                            end
                        end
                        SafeSetVehicleCanBeVisiblyDamaged(vehicle, true)
                        SafeSetVehicleStrong(vehicle, false)
                    end
                end
            end

            SafeThread(function()
                restoreVehicleCollisions()
            end)
        ]])

        MachoMenuNotification("Amiwa Menu", "Vehicle - collision disabled!")
    end
)
MachoMenuCheckbox(SpawnVehiclesSection, "Invisible Car", 
    function()
        if GetResourceState("WaveShield") == "started" then
            MachoMenuNotification("Amiwa Menu", "WaveShield Detected!")
            return
        end

                        if GetResourceState("ReaperV4") == "started" then
            MachoMenuNotification("Amiwa Menu", "ReaperV4 Detected!")
            return
        end

        MachoInjectResourceRaw(GetAvailableResource(), [[
            _G.isInvisibleCarEnabled = true
            
            local function decode(tbl)
                local s = ""
                for i = 1, #tbl do s = s .. string.char(tbl[i]) end
                return s
            end

            local function g(n)
                return _G[decode(n)]
            end

            local function wait(n)
                return Citizen.Wait(n)
            end

            local function setVehicleInvisible()
                local playerPed = g({80,108,97,121,101,114,80,101,100,73,100})() -- PlayerPedId
                if not g({68,111,101,115,69,110,116,105,116,121,69,120,105,115,116})(playerPed) then return false end -- DoesEntityExist

                if g({73,115,80,101,100,73,110,65,110,121,86,101,104,105,99,108,101})(playerPed, false) then -- IsPedInAnyVehicle
                    local vehicle = g({71,101,116,86,101,104,105,99,108,101,80,101,100,73,115,73,110})(playerPed, false) -- GetVehiclePedIsIn
                    
                    if vehicle and g({68,111,101,115,69,110,116,105,116,121,69,120,105,115,116})(vehicle) then -- DoesEntityExist
                        -- Make the vehicle invisible
                        g({83,101,116,69,110,116,105,116,121,86,105,115,105,98,108,101})(vehicle, false, false) -- SetEntityVisible
                        -- Ensure the player remains visible
                        g({83,101,116,69,110,116,105,116,121,86,105,115,105,98,108,101})(playerPed, true, false) -- SetEntityVisible
                        return true
                    end
                end
                return false
            end

            g({67,114,101,97,116,101,84,104,114,101,97,100})(function() -- CreateThread
                while _G.isInvisibleCarEnabled do
                    setVehicleInvisible()
                    wait(0)
                end
            end)
        ]])
        MachoMenuNotification("Amiwa Menu", "Invisible car enabled!")
    end,
    function()
        MachoInjectResourceRaw(GetAvailableResource(), [[
            _G.isInvisibleCarEnabled = false
            
            local function decode(tbl)
                local s = ""
                for i = 1, #tbl do s = s .. string.char(tbl[i]) end
                return s
            end

            local function g(n)
                return _G[decode(n)]
            end

            local function restoreVehicleVisibility()
                local playerPed = g({80,108,97,121,101,114,80,101,100,73,100})() -- PlayerPedId
                if g({73,115,80,101,100,73,110,65,110,121,86,101,104,105,99,108,101})(playerPed, false) then -- IsPedInAnyVehicle
                    local vehicle = g({71,101,116,86,101,104,105,99,108,101,80,101,100,73,115,73,110})(playerPed, false) -- GetVehiclePedIsIn
                    if vehicle and g({68,111,101,115,69,110,116,105,116,121,69,120,105,115,116})(vehicle) then -- DoesEntityExist
                        -- Restore vehicle visibility
                        g({83,101,116,69,110,116,105,116,121,86,105,115,105,98,108,101})(vehicle, true, false) -- SetEntityVisible
                        -- Ensure player remains visible
                        g({83,101,116,69,110,116,105,116,121,86,105,115,105,98,108,101})(playerPed, true, false) -- SetEntityVisible
                    end
                end
            end

            g({67,114,101,97,116,101,84,104,114,101,97,100})(function() -- CreateThread
                restoreVehicleVisibility()
                collectgarbage("collect")
            end)
        ]])
        MachoMenuNotification("Amiwa Menu", "Invisible car disabled!")
    end
)
MachoMenuCheckbox(SpawnVehiclesSection, "Anti VDM (Risk)", 
    function()
        _G.isAntiVDMEnabled = true

        MachoInjectResourceRaw(GetAvailableResource(), [[
            local function SafeWrap(setFunc)
                return function(...)
                    return setFunc(...)
                end
            end

            local SafeThread = SafeWrap(CreateThread)
            local SafePlayerPedId = SafeWrap(PlayerPedId)
            local SafeDoesEntityExist = SafeWrap(DoesEntityExist)
            local SafeGetGamePool = SafeWrap(GetGamePool)
            local SafeSetEntityNoCollisionEntity = SafeWrap(SetEntityNoCollisionEntity)
            local SafeWait = SafeWrap(Citizen.Wait)

            SafeThread(function()
                while _G.isAntiVDMEnabled do
                    local playerPed = SafePlayerPedId()
                    if SafeDoesEntityExist(playerPed) then
                        local vehicles = SafeGetGamePool('CVehicle')
                        for _, veh in ipairs(vehicles) do
                            if SafeDoesEntityExist(veh) then
                                SafeSetEntityNoCollisionEntity(playerPed, veh, true)
                                SafeSetEntityNoCollisionEntity(veh, playerPed, true)
                            end
                        end
                    end
                    SafeWait(0)
                end
            end)
        ]])

        MachoMenuNotification("Amiwa Menu", "Anti VDM Enabled!")
    end,

    function()
        _G.isAntiVDMEnabled = false

        MachoInjectResourceRaw(GetAvailableResource(), [[
            local function SafeWrap(setFunc)
                return function(...)
                    return setFunc(...)
                end
            end

            local SafeThread = SafeWrap(CreateThread)
            local SafePlayerPedId = SafeWrap(PlayerPedId)
            local SafeDoesEntityExist = SafeWrap(DoesEntityExist)
            local SafeGetGamePool = SafeWrap(GetGamePool)
            local SafeSetEntityNoCollisionEntity = SafeWrap(SetEntityNoCollisionEntity)

            SafeThread(function()
                local playerPed = SafePlayerPedId()
                if SafeDoesEntityExist(playerPed) then
                    local vehicles = SafeGetGamePool('CVehicle')
                    for _, veh in ipairs(vehicles) do
                        if SafeDoesEntityExist(veh) then
                            SafeSetEntityNoCollisionEntity(playerPed, veh, false)
                            SafeSetEntityNoCollisionEntity(veh, playerPed, false)
                        end
                    end
                end
            end)
        ]])

        MachoMenuNotification("Amiwa Menu", "Anti VDM Disabled!")
    end
)
MachoMenuCheckbox(SpawnVehiclesSection, "Drive To Waypoint",
    function()
        if isAutoDriveActive then return end -- Prevent multiple instances
        isAutoDriveActive = true
            MachoInjectResourceRaw(GetAvailableResource(), [[
            local autoDriveEnabled = true
            
            Citizen.CreateThread(function()
                local ped = PlayerPedId()
                
                while autoDriveEnabled do
                    Citizen.Wait(0)
                    
                    if DoesBlipExist(GetFirstBlipInfoId(8)) then
                        local blip = GetFirstBlipInfoId(8)
                        local wp = Citizen.InvokeNative(0xFA7C7F0AADF25D09, blip, Citizen.ResultAsVector())
                        
                        if wp then
                            local vehicle = GetVehiclePedIsIn(ped, false)
                            if vehicle ~= 0 and GetPedInVehicleSeat(vehicle, -1) == ped then
                                -- Crazy and fast driving!
                                local speed = 200.0
                                local drivingStyle = 786603 -- Most aggressive: Ignore lights, lanes, traffic, brakes, EVERYTHING
                                
                                TaskVehicleDriveToCoord(ped, vehicle, wp.x, wp.y, wp.z, speed, 0, GetEntityModel(vehicle), drivingStyle, 10.0)
                            end
                        end
                    end
                    
                    Citizen.Wait(2000)
                end
            end)
            
            -- Expose a function to stop the loop
            _G["]] .. resourceId .. [[_stop"] = function()
                autoDriveEnabled = false
                local ped = PlayerPedId()
                ClearPedTasksImmediately(ped) -- Clear driving tasks immediately
            end
        ]])
    end,
    function()
        if not isAutoDriveActive then return end
        isAutoDriveActive = false
            MachoInjectResourceRaw(GetAvailableResource(), [[
            -- Stop the auto-drive loop and clear tasks
            if _G["]] .. resourceId .. [[_stop"] then
                _G["]] .. resourceId .. [[_stop"]()
                _G["]] .. resourceId .. [[_stop"] = nil -- Clean up the stop function
            end
        ]])
    end
)
