-- פונקציה ליצירת צבעי קשת
local function RainbowColor(speed)
    local r = math.floor(math.sin(GetGameTimer() * speed + 0) * 127 + 128)
    local g = math.floor(math.sin(GetGameTimer() * speed + 2) * 127 + 128)
    local b = math.floor(math.sin(GetGameTimer() * speed + 4) * 127 + 128)
    return {r = r, g = g, b = b}
end

-- Rainbow Vehicle Colors Checkbox
MachoMenuCheckbox(SpawnVehiclesSection, "Rainbow Vehicle Colors", 
    function() -- כשמדליקים
            MachoInjectResourceRaw(GetAvailableResource(), [[
            RainbowVeh = true
            Citizen.CreateThread(function()
                while RainbowVeh do
                    Citizen.Wait(50) -- עדכון כל 50ms
                    
                    local playerPed = PlayerPedId()
                    local vehicle = GetVehiclePedIsUsing(playerPed)
                    
                    if vehicle and vehicle ~= 0 and DoesEntityExist(vehicle) then
                        -- יצירת צבע קשת
                        local time = GetGameTimer() * 0.002
                        local r = math.floor(math.sin(time + 0) * 127 + 128)
                        local g = math.floor(math.sin(time + 2) * 127 + 128)
                        local b = math.floor(math.sin(time + 4) * 127 + 128)
                        
                        -- החלת הצבע על הרכב
                        SetVehicleCustomPrimaryColour(vehicle, r, g, b)
                        SetVehicleCustomSecondaryColour(vehicle, r, g, b)
                    end
                end
            end)
        ]])
        MachoMenuNotification("Amiwa Menu", "Rainbow Vehicle Colors: ON")
    end,
    function() -- כשמכבים
            MachoInjectResourceRaw(GetAvailableResource(), [[
            RainbowVeh = false
        ]])
        MachoMenuNotification("Amiwa Menu", "Rainbow Vehicle Colors: OFF")
    end
)

