    -- מעבר לצבע הבא
    currentColorIndex = currentColorIndex + 1
    if currentColorIndex > #carColors then
        currentColorIndex = 1
    end
    
    local colorData = carColors[currentColorIndex]
    
        MachoInjectResourceRaw(GetAvailableResource(), [[
        -- עדכון מיידי של צבע הרכב
        local playerPed = PlayerPedId()
        local vehicle = GetVehiclePedIsUsing(playerPed)
        
        if vehicle and vehicle ~= 0 and DoesEntityExist(vehicle) then
            local primaryColor = ]] .. colorData.primary .. [[
            local secondaryColor = ]] .. colorData.secondary .. [[
            
            -- החלת הצבע על הרכב
            SetVehicleColours(vehicle, primaryColor, secondaryColor)
            
            -- עדכון נוסף כדי לוודא שהצבע השתנה
