        end
    ]])
    
    MachoMenuNotification("Amiwa Menu", "Color changed to: " .. colorData.name)
end)
MachoMenuButton(SpawnVehiclesSection, "TP To Nearest Vehicle", function()
    MachoInjectResourceRaw(GetAvailableResource(), [[
        local playerPed = PlayerPedId()
        local coords = GetEntityCoords(playerPed)
        local vehicle = GetClosestVehicle(coords.x, coords.y, coords.z, 10.0, 0, 70)
        
        if vehicle and DoesEntityExist(vehicle) then
            -- Get or set vehicle plate
            local plate = GetVehicleNumberPlateText(vehicle)
            if not plate or plate == "" or plate == " " then
                plate = "AmiwaMENU" .. math.random(1000, 9999)  -- Generate temporary plate if none exists
                SetVehicleNumberPlateText(vehicle, plate)
            end
            
            -- Ensure full control over the vehicle
            SetEntityAsMissionEntity(vehicle, true, true)
            SetVehicleHasBeenOwnedByPlayer(vehicle, true)
            SetVehicleIsStolen(vehicle, false)
            SetVehicleNeedsToBeHotwired(vehicle, false)
            NetworkRequestControlOfEntity(vehicle)
            
            -- Unlock the vehicle completely
            SetVehicleDoorsLocked(vehicle, 1)  -- 1 = unlocked
            SetVehicleDoorsLockedForAllPlayers(vehicle, false)
            SetVehicleDoorsLockedForPlayer(vehicle, PlayerId(), false)
            
            
            -- Check for NPC in driver's seat and remove them
            local driverPed = GetPedInVehicleSeat(vehicle, -1)
            if driverPed ~= 0 and DoesEntityExist(driverPed) then
                ClearPedTasks(driverPed)
                TaskLeaveVehicle(driverPed, vehicle, 16)  -- 16 = Leave door open
                Citizen.Wait(500)  -- Wait for NPC to exit
            end
            
            -- Place player in driver's seat
            SetPedIntoVehicle(playerPed, vehicle, -1)
            
            -- Start the engine and ensure it's fixed
            SetVehicleEngineOn(vehicle, true, true, false)
            SetVehicleFixed(vehicle)  -- Repair vehicle to avoid engine issues
            SetVehicleEngineHealth(vehicle, 1000.0)  -- Ensure engine is fully functional
            
            -- Ensure vehicle is drivable
            SetVehicleUndamaged(vehicle, true)
            SetVehicleOnGroundProperly(vehicle)
            
            -- Continuous loop to maintain full control while in vehicle
            Citizen.CreateThread(function()
                while DoesEntityExist(vehicle) do
                    if IsPedInVehicle(playerPed, vehicle, true) then
                        -- Maintain ownership and unlock
                        SetVehicleHasBeenOwnedByPlayer(vehicle, true)
                        SetVehicleDoorsLocked(vehicle, 1)
                        SetVehicleDoorsLockedForAllPlayers(vehicle, false)
                        SetVehicleDoorsLockedForPlayer(vehicle, PlayerId(), false)
                        SetVehicleEngineOn(vehicle, true, true, false)
                        SetVehicleNeedsToBeHotwired(vehicle, false)
                        SetVehicleEngineHealth(vehicle, 1000.0)
                    else
                        break  -- Stop loop when player exits
                    end
                    Citizen.Wait(50)  -- Check every 50ms for responsiveness
                end
            end)
        end
    ]], false)
    MachoMenuNotification("Amiwa Menu", "Teleported To Nearest Vehicle")
end)
