MachoMenuText(ExploitSection, "Safe Triggers (Execute)")
ScriptInput = MachoMenuInputbox(ExploitSection, "Script Name:", "monitor")
TriggerInput = MachoMenuInputbox(ExploitSection, "Trigger Name:", "TriggerServerEvent('QBCore:Server:AddItem')")
AmountInput = MachoMenuInputbox(ExploitSection, "Execute Amount (optional):", "1")

MachoMenuButton(ExploitSection, "Execute Trigger", function()
    local scriptName = MachoMenuGetInputbox(ScriptInput)
    local triggerName = MachoMenuGetInputbox(TriggerInput)
    local amountInputValue = MachoMenuGetInputbox(AmountInput)
    local amount = tonumber(amountInputValue)

    if scriptName and scriptName ~= "" and triggerName and triggerName ~= "" then
        -- בדיקה אם הטריגר מכיל סוגריים סגורות, כלומר פרמטרים מלאים
        local hasParameters = triggerName:match("%(.*%)$") ~= nil
        local injectCode

        if hasParameters then
            -- אם יש פרמטרים, הזרק את הטריגר כפי שהוא
            injectCode = [[
                local function SafeTriggers()
                    return ]] .. triggerName .. [[
                end
                SafeTriggers()
            ]]
        else
            -- אם אין פרמטרים, הוסף את Amount כפרמטר
            if amount and amount > 0 then
                injectCode = [[
                    local function SafeTriggers(Amount)
                        return ]] .. triggerName .. [[, Amount)
                    end
                    SafeTriggers(]] .. amount .. [[)
                ]]
            else
                injectCode = [[
                    local function SafeTriggers()
                        return ]] .. triggerName .. [[)
                    end
                    SafeTriggers()
                ]]
            end
        end

        MachoInjectResourceRaw(scriptName, injectCode)
        MachoMenuNotification("Amiwa Menu", "Executed trigger: " .. triggerName .. (amount and amount > 0 and " with amount: " .. amount or "") .. " on script: " .. scriptName)
    else
        if not scriptName or scriptName == "" then
            MachoMenuNotification("Amiwa Menu", "Enter a valid script name!")
        elseif not triggerName or triggerName == "" then
            MachoMenuNotification("Amiwa Menu", "Enter a valid trigger name!")
        else
            MachoMenuNotification("Amiwa Menu", "Invalid input! Check all fields")
        end
    end
end)
