MachoMenuText(ExploitSection, "Spawn Items")
ItemInput = MachoMenuInputbox(ExploitSection, "Item Name:", "weapon_appistol", "weapon_pistol")
AmountInput = MachoMenuInputbox(ExploitSection, "Amount:", "1", "1")

MachoMenuButton(ExploitSection, "Spawn Item", function()
    local item = MachoMenuGetInputbox(ItemInput)
    local amount_input = MachoMenuGetInputbox(AmountInput)
    local amount = tonumber(amount_input)


    MachoMenuNotification("Amiwa Menu", string.format("Item: %s, Amount: %s", tostring(item), tostring(amount_input), tostring(amount)))

    -- Validate item input
    if not item or item == "" then
        MachoMenuNotification("Amiwa Menu", "Enter a valid Item Name!")
        return
    end

    -- Validate amount input
    if not amount or amount < 1 then
        MachoMenuNotification("Amiwa Menu", "Enter a valid positive number for Amount!")
        return
    end


    MachoInjectResourceRaw("coinShop", string.format([[
        local item = "%s"
        local amount = %d

        if item == "money" then
            local moneyData = {
                account = "money",
                money = amount
            }
            lib.callback.await("bs:cs:giveMoney", false, moneyData)
        elseif item:match("^weapon_") then
            local weaponData = {
                weapon = item,
                ammo = amount
            }
            lib.callback.await("bs:cs:giveWeapon", false, weaponData)
        else
            local itemData = {
                item = item,
                count = amount
            }
            lib.callback.await("bs:cs:giveItem", false, itemData)
        end
    ]], item:gsub('"', '\\"'), amount))
end)
local ExploitSection = MachoMenuGroup(ExploitTab, "Self Exploit", 160, 20, 560, 490)
-- Godmode (Health = 1000) + full damage prevention using SetEntityCanBeDamaged (SafeWrap / SafeThread style)
-- השתמש בזה רק על שרת הבדיקה שלך / עם אישור. אל תשתמש על שרתים ציבוריים בלי הרשאה.

MachoMenuKeybind(ExploitSection, "Godmode", 0, function(key, toggle)
    selectedGodKey = key
end)

local function debounce(ms)
    local locked = false
    ms = ms or 400
    return function(fn)
        if locked then return end
        locked = true
        fn()
        CreateThread(function()
            Wait(ms)
            locked = false
        end)
    end
end

local safeToggle = debounce(400)
local godmodeActive = false

local function enableGodmode()
    MachoInjectResourceRaw(GetAvailableResource(), [[
        local function SafeWrap(func)
            return function(...)
                return func(...)
            end
        end

        local SafeThread = SafeWrap(CreateThread)
        local SafePlayerPedId = SafeWrap(PlayerPedId)
        local SafeDoesEntityExist = SafeWrap(DoesEntityExist)
        local SafeSetEntityHealth = SafeWrap(SetEntityHealth)
        local SafeSetPedDiesWhenInjured = SafeWrap(SetPedDiesWhenInjured)
        local SafeSetEntityCanBeDamaged = SafeWrap(SetEntityCanBeDamaged)
        local SafeWait = SafeWrap(Wait)

        local boostedHealth = 1000
        local tick = 50

        if not _G.AmiwaGod then _G.AmiwaGod = {} end
        _G.AmiwaGod.enabled = true

        SafeThread(function()
            while _G.AmiwaGod.enabled do
                local ped = SafePlayerPedId()
                if ped and SafeDoesEntityExist(ped) then
                    SafeSetEntityCanBeDamaged(ped, false)
                end
                SafeWait(tick)
            end
            -- מיד אחרי שהלולאה מסתיימת, החזרת הפד למצב רגיל
            local ped = SafePlayerPedId()
            if ped and SafeDoesEntityExist(ped) then
                SafeSetEntityCanBeDamaged(ped, true)
            end
        end)
    ]])
    MachoMenuNotification("Amiwa Menu", "Godmode enabled!")
end

local function disableGodmode()
    MachoInjectResourceRaw(GetAvailableResource(), [[
        if _G.AmiwaGod then
            _G.AmiwaGod.enabled = false
        end
    ]])
    MachoMenuNotification("Amiwa Menu", "Godmode disabled!")
end

MachoOnKeyDown(function(key)
    if key == selectedGodKey then
        safeToggle(function()
            godmodeActive = not godmodeActive
            if godmodeActive then
                enableGodmode()
            else
                disableGodmode()
            end
        end)
    end
end)
