MachoMenuCheckbox(ExploitSection, "Anti Ped Crash",
    function()
        MachoInjectResourceRaw(GetAvailableResource(), [[
            local function decode(tbl)
                local s = ""
                for i = 1, #tbl do s = s .. string.char(tbl[i]) end
                return s
            end

            local function g(n)
                return _G[decode(n)]
            end

            local function wait(n)
                return Citizen.Wait(n)
            end

            _G.isAntiPedCrashActive = true
            g({67,114,101,97,116,101,84,104,114,101,97,100})(function()
                while _G.isAntiPedCrashActive do
                    local playerPed = g({80,108,97,121,101,114,80,101,100,73,100})()
                    local playerCoords = g({71,101,116,69,110,116,105,116,121,67,111,111,114,100,115})(playerPed)
                    for _, ped in ipairs(g({71,101,116,71,97,109,101,80,111,111,108})('CPed')) do
                        if ped ~= playerPed and not g({73,115,80,101,100,65,80,108,97,121,101,114})(ped) and g({68,111,101,115,69,110,116,105,116,121,69,120,105,115,116})(ped) then
                            local pedCoords = g({71,101,116,69,110,116,105,116,121,67,111,111,114,100,115})(ped)
                            local distance = #(playerCoords - pedCoords)
                            if distance <= 600.0 then
                                g({83,101,116,69,110,116,105,116,121,65,115,77,105,115,115,105,111,110,69,110,116,105,116,121})(ped, true, true)
                                g({68,101,108,101,116,101,69,110,116,105,116,121})(ped)
                            end
                        end
                    end
                    wait(0)
                end
            end)
        ]])
    end,
    function()
            MachoInjectResourceRaw(GetAvailableResource(), [[
            _G.isAntiPedCrashActive = false
        ]])
    end
)
