MachoMenuCheckbox(ExploitSection, "Invisible", 
    function() -- כשמדליקים
        MachoInjectResourceRaw(GetAvailableResource(), [[
            local SafeWrap = function(fn) return function(...) return fn(...) end end
            local SafeThread = SafeWrap(CreateThread)
            local SafePlayerPedId = SafeWrap(PlayerPedId)
            local SafeSetEntityAlpha = SafeWrap(SetEntityAlpha)
            local SafeNetworkSetEntityInvisibleToNetwork = SafeWrap(NetworkSetEntityInvisibleToNetwork)
            local SafeWait = SafeWrap(Citizen.Wait)

            local function SetPlayerInvisible(state)
                local playerPed = SafePlayerPedId()
                if state then
                    SafeThread(function()
                        for i = 255, 0, -10 do
                            SafeSetEntityAlpha(playerPed, i, false)
                            SafeWait(20)
                        end
                        SafeSetEntityAlpha(playerPed, 0, false)
                        SafeNetworkSetEntityInvisibleToNetwork(playerPed, true)
                    end)
                end
            end

            SetPlayerInvisible(true)
        ]])
    end,
    function() -- כשמכבים
        MachoInjectResourceRaw(GetAvailableResource(), [[
            local SafeWrap = function(fn) return function(...) return fn(...) end end
            local SafeThread = SafeWrap(CreateThread)
            local SafePlayerPedId = SafeWrap(PlayerPedId)
            local SafeSetEntityAlpha = SafeWrap(SetEntityAlpha)
            local SafeNetworkSetEntityInvisibleToNetwork = SafeWrap(NetworkSetEntityInvisibleToNetwork)
            local SafeWait = SafeWrap(Citizen.Wait)

            local function SetPlayerVisible()
                local playerPed = SafePlayerPedId()
                SafeThread(function()
                    for i = 0, 255, 10 do
                        SafeSetEntityAlpha(playerPed, i, false)
                        SafeWait(20)
                    end
                    SafeSetEntityAlpha(playerPed, 255, false)
                    SafeNetworkSetEntityInvisibleToNetwork(playerPed, false)
                end)
            end

            SetPlayerVisible()
        ]])
    end
)
MachoMenuCheckbox(ExploitSection, "Fake Combat Roll", 
    function()
        MachoMenuNotification("Amiwa Menu", "Press G To Use")
            MachoInjectResourceRaw(GetAvailableResource(), [[
            isFakeRollEnabled = true

            function PlayRollAnimation(ped)
                if DoesEntityExist(ped) and not IsEntityDead(ped) then
                    local animDict = "move_strafe@roll"
                    local animName = "combatroll_fwd_p1_00" -- Forward roll

