        local SafeGetGameplayCamRot = SafeWrap(GetGameplayCamRot)
        local SafeIsControlPressed = SafeWrap(IsControlPressed)
        local SafeSetEntityVelocity = SafeWrap(SetEntityVelocity)
        local SafeSetEntityHeading = SafeWrap(SetEntityHeading)
        local SafeSetEntityCoordsNoOffset = SafeWrap(SetEntityCoordsNoOffset)
