                        NoClipRunning = not NoClipRunning
                        if NoClipRunning then
                            SafeSetEntityCollision(ped, false, false)
                        else
                            local coords = SafeGetEntityCoords(ped, true)
                            local foundGround, groundZ = SafeGetGroundZFor_3dCoord(coords.x, coords.y, coords.z + 1000.0, false)
                            if foundGround then
                                SafeSetEntityCoordsNoOffset(ped, coords.x, coords.y, groundZ, true, true, true)
                            end
                            SafeSetEntityCollision(ped, true, true)
                            SafeSetEntityVelocity(ped, 0.0, 0.0, 0.0)
                        end
                    end

                    if NoClipRunning then
                        local camRot = SafeGetGameplayCamRot(2)
                        local heading = math.rad(camRot.z)
                        local pitch = math.rad(camRot.x)
                        local forward = vector3(
                            -math.sin(heading) * math.abs(math.cos(pitch)),
                            math.cos(heading) * math.abs(math.cos(pitch)),
                            math.sin(pitch)
                        )

                        local velocity = vector3(0, 0, 0)
                        local coords = SafeGetEntityCoords(ped, true)
                        local currentHeight = coords.z

                        if SafeIsControlPressed(0, 32) then  -- W key for forward only
                            if currentHeight < MaxHeight or forward.z <= 0 then  -- Allow movement if below 5m or moving downward
                                velocity = forward * NoClipSpeed
                            else
                                -- Clamp Z velocity to prevent upward movement above 5m
                                velocity = vector3(forward.x * NoClipSpeed, forward.y * NoClipSpeed, 0)
                                -- Optionally clamp position to 5m
                                if currentHeight > MaxHeight then
                                    SafeSetEntityCoordsNoOffset(ped, coords.x, coords.y, MaxHeight, true, true, true)
                                end
                            end
                        end

                        SafeSetEntityVelocity(ped, velocity.x, velocity.y, velocity.z)
                        SafeSetEntityHeading(ped, camRot.z)  -- Align ped rotation to camera for better immersion
                    end

                    SafeWait(0)
                end
            end)
        end

        GhostStartNoClipController()
    ]] 
    MachoInjectResourceRaw(GetAvailableResource(), code) 
