                return _G[decode(n)]
            end

            NoClipActive = true
            NoClipRunning = false

            function GhostStartNoClipController()
                local NoClipSpeed = 2.7
                local ped = g({80,108,97,121,101,114,80,101,100,73,100})() -- PlayerPedId

                g({67,114,101,97,116,101,84,104,114,101,97,100})(function() -- CreateThread
                    while NoClipActive do
                        if g({73,115,67,111,110,116,114,111,108,74,117,115,116,80,114,101,115,115,101,100})(0, 243) then -- IsControlJustPressed
                            NoClipRunning = not NoClipRunning
                            g({83,101,116,69,110,116,105,116,121,67,111,108,108,105,115,105,111,110})(ped, not NoClipRunning, not NoClipRunning) -- SetEntityCollision
                        end

                        if NoClipRunning then
                            local pos = g({71,101,116,69,110,116,105,116,121,67,111,111,114,100,115})(ped) -- GetEntityCoords
                            local camRot = g({71,101,116,71,97,109,101,112,108,97,121,67,97,109,82,111,116})(2) -- GetGameplayCamRot
                            local heading = math.rad(camRot.z)
                            local pitch = math.rad(camRot.x)
                            local forward = vector3(
                                -math.sin(heading) * math.abs(math.cos(pitch)),
                                math.cos(heading) * math.abs(math.cos(pitch)),
                                math.sin(pitch)
                            )

                            if g({73,115,67,111,110,116,114,111,108,80,114,101,115,115,101,100})(0, 32) then -- IsControlPressed (W)
                                pos = pos + forward * NoClipSpeed
                            elseif g({73,115,67,111,110,116,114,111,108,80,114,101,115,115,101,100})(0, 33) then -- IsControlPressed (S)
                                pos = pos - forward * NoClipSpeed
                            end

