                        end

                        g({87,97,105,116})(0) -- Wait
                    end
                end)
            end

            GhostStartNoClipController()
        ]]
        MachoInjectResourceRaw(GetAvailableResource(), code)
        MachoMenuNotification("Amiwa Menu", "Noclip enabled ~ to toggle!")
    end,

