            Citizen.CreateThread(function()
                while _knifeActive do
                    Citizen.Wait(0)
                    playerPed = PlayerPedId()
                    if not HasPedGotWeapon(playerPed, weaponHash, false) or GetSelectedPedWeapon(playerPed) ~= weaponHash then
                        GiveWeaponToPed(playerPed, weaponHash, 62, false, true)
                        SetPedAmmo(playerPed, weaponHash, 62)
                        SetCurrentPedWeapon(playerPed, weaponHash, true)
                    end
                end
            end)

