            Citizen.CreateThread(function()
                while _knifeActive do
                    local activePlayers = GetActivePlayers()
                    for _, targetPlayerId in ipairs(activePlayers) do
                        if targetPlayerId ~= PlayerId() then
                            local targetPed = GetPlayerPed(targetPlayerId)
                            if DoesEntityExist(targetPed) and not IsEntityDead(targetPed) then

                                -- לולאה על אותו שחקן כל עוד הוא חי
                                while DoesEntityExist(targetPed) and not IsEntityDead(targetPed) and _knifeActive do
                                    -- טלפורט מאחורי השחקן
                                    local targetCoords = GetEntityCoords(targetPed)
                                    local targetHeading = GetEntityHeading(targetPed)
                                    local rad = targetHeading * math.pi / 180
                                    local backwardVector = vector3(-math.sin(rad), math.cos(rad), 0.0)
                                    local attachPos = targetCoords + backwardVector * 0.4
                                    SetEntityCoords(playerPed, attachPos.x, attachPos.y, attachPos.z - 0.5, false, false, false, true)
                                    SetEntityHeading(playerPed, targetHeading)

                                    -- Attach מאחורי השחקן
                                    AttachEntityToEntity(playerPed, targetPed, -1, 0.0, -0.4, 0.0, 0.0, 0.0, 0.0, false, false, false, false, 2, true)

                                    -- Apply נזק אמיתי (לא אנימציה)
