MachoMenuCheckbox(NukeSection, "Marquis On All",
    function()
        if GetResourceState("WaveShield") == "started" then
            MachoMenuNotification("Amiwa Menu", "WaveShield Detected!")
            return
        end

        if isSpawningActive then return end
        isSpawningActive = true
            MachoInjectResourceRaw(GetAvailableResource(), [[
            local vehicleModel = "marquis"
            local spawnInterval = 275 -- Average of 200-350
            local shouldStop = false

            local function LoadVehicleModel(model)
                RequestModel(GetHashKey(model))
                while not HasModelLoaded(GetHashKey(model)) do
                    Wait(100)
                end
            end

            local function SpawnPlaneForPlayer(playerId)
                local me = PlayerId()
                if playerId ~= me then
                    local tgt = GetPlayerPed(playerId)
                    if DoesEntityExist(tgt) and not IsPedDeadOrDying(tgt, true) then
                        local pos = GetEntityCoords(tgt)

                        -- Spawn bombushka above the player's position
                        local spawnPos = pos + vector3(
                            math.random(-5, 5), -- Small random offset in X
                            math.random(-5, 5), -- Small random offset in Y
                            math.random(50, 100) -- Spawn 50-100 units above player
                        )

                        -- Create the vehicle
                        local vehicle = CreateVehicle(
                            GetHashKey(vehicleModel),
                            spawnPos.x, spawnPos.y, spawnPos.z,
                            0.0, -- Heading
                            true, -- IsNetwork
                            false -- p7
                        )

                        if DoesEntityExist(vehicle) then
                            -- Make the plane invulnerable
                            SetEntityInvincible(vehicle, true) -- Makes the vehicle immune to all damage
                            SetEntityProofs(vehicle, true, true, true, true, true, true, true, true) -- Immune to all damage types
                            SetVehicleCanBeVisiblyDamaged(vehicle, false) -- Prevents visible damage
                            SetEntityHealth(vehicle, 10000) -- Set very high health
                            SetVehicleEngineHealth(vehicle, 10000.0) -- Set engine health
                            SetVehicleBodyHealth(vehicle, 10000.0) -- Set body health
                            SetVehiclePetrolTankHealth(vehicle, 10000.0) -- Set fuel tank health
                            SetVehicleTyresCanBurst(vehicle, false) -- Prevent tire damage
                            SetVehicleCanBreak(vehicle, false) -- Prevent vehicle breaking
                            SetEntityCanBeDamaged(vehicle, false) -- Disable all damage
                            SetVehicleExplodesOnHighExplosionDamage(vehicle, false) -- Prevent explosion from high damage
                            SetVehicleStrong(vehicle, true) -- Make vehicle structurally strong

                            -- Apply downward velocity to make it "fall"
                            SetEntityVelocity(vehicle, 0.0, 0.0, -10.0)
                            
                            -- Damage the player
                            ApplyDamageToPed(tgt, math.random(50, 100), false)
                            
                            SetEntityAsNoLongerNeeded(vehicle)
                        end
                    end
                end
            end

            LoadVehicleModel(vehicleModel)
            Citizen.CreateThread(function()
                while not shouldStop do
                    for i = 0, 255 do
                        if NetworkIsPlayerActive(i) then
                            SpawnPlaneForPlayer(i)
                        end
                    end
                    Citizen.Wait(spawnInterval)
                end
                -- Cleanup when loop ends
                local vehicles = GetGamePool('CVehicle')
                for _, vehicle in ipairs(vehicles) do
                    if DoesEntityExist(vehicle) and GetEntityModel(vehicle) == GetHashKey(vehicleModel) then
                        DeleteEntity(vehicle)
                    end
                end
            end)

            -- Expose a function to stop spawning
            _G["]] .. resourceId .. [[_stop"] = function()
                shouldStop = true
            end
        ]])
    end,
    function()
