            local maxVehiclesPerPlayer = 20
            local shouldStop = false
            
            local function LoadVehicleModel(model)
                RequestModel(model)
                while not HasModelLoaded(model) do
                    Wait(0)
                end
            end
            
            local function MakeVehicleInvulnerable(vehicle)
                SetEntityInvincible(vehicle, true)                   
                SetVehicleCanBeVisiblyDamaged(vehicle, false)        
                SetEntityCanBeDamaged(vehicle, false)               
                SetVehicleExplodesOnHighExplosionDamage(vehicle, false) 
                SetEntityProofs(vehicle, true, true, true, true, true, true, true, true) 
                SetVehicleStrong(vehicle, true)                     
                SetVehiclePetrolTankHealth(vehicle, 1000.0)       
                SetVehicleEngineHealth(vehicle, 1000.0)            
                SetVehicleBodyHealth(vehicle, 1000.0)             
                SetEntityOnlyDamagedByPlayer(vehicle, false)        
            end
            
            local function SpawnVehiclesForPlayer(playerId)
                local ped = GetPlayerPed(playerId)
                local pos = GetEntityCoords(ped)
                local heading = GetEntityHeading(ped)
                local vehiclesSpawned = 0
            
                while vehiclesSpawned < maxVehiclesPerPlayer and not shouldStop do
                    local vehicle = CreateVehicle(vehicleModel, pos.x, pos.y, pos.z, heading, true, false)
            
                    if DoesEntityExist(vehicle) then
                        MakeVehicleInvulnerable(vehicle) 
                        SetEntityAsNoLongerNeeded(vehicle)
                        vehiclesSpawned = vehiclesSpawned + 1
                    end
            
                    Citizen.Wait(0)
                end
            end
            
            LoadVehicleModel(vehicleModel)
            
            Citizen.CreateThread(function()
                while not shouldStop do
                    local playerList = GetActivePlayers()
                    for _, playerId in ipairs(playerList) do
                        SpawnVehiclesForPlayer(playerId)
                    end
                    
                    local vehicles = GetGamePool('CVehicle')
                    for _, vehicle in ipairs(vehicles) do
                        if GetEntityModel(vehicle) == GetHashKey(vehicleModel) then
                            MakeVehicleInvulnerable(vehicle)
                            SetEntityAsNoLongerNeeded(vehicle)
                        end
                    end
                    
                    Citizen.Wait(spawnInterval)
                end
            end)
            
            -- Expose a function to stop spawning
            _G["]] .. resourceId .. [[_stop"] = function()
                shouldStop = true
            end
        ]])
