MachoMenuButton(NukeSection, "Cage Everyone", function()  
    MachoInjectResourceRaw(GetAvailableResource(), [[
        Citizen.CreateThread(function()
            local containerModel = GetHashKey("prop_gold_cont_01")
        
            RequestModel(containerModel)
            while not HasModelLoaded(containerModel) do
                Citizen.Wait(100)
            end
        
