                            SetEntityVisible(container, true, 0)
                            FreezeEntityPosition(container, true)
        
                            SetEntityCoordsNoOffset(container, pedCoords.x, pedCoords.y, groundZ + 1.0, true, true, true)
                        end
                    end
                end
            end
        end)   
      ]])
    end)
