MachoMenuButton(NukeSection, "Taze All Players (Risk)", function()
        MachoInjectResourceRaw(GetAvailableResource(), [[
        local function SilentStunPlayer(playerServerId)
            local playerId = GetPlayerFromServerId(playerServerId)
            if playerId then
                local targetPed = GetPlayerPed(playerId)
                local targetCoords = GetEntityCoords(targetPed)
                local targetHeading = GetEntityHeading(targetPed)

                local npcModel = GetHashKey('s_m_y_blackops_01')
                RequestModel(npcModel)

                local modelLoadTimeout = 10000
                local startTime = GetGameTimer()

                while not HasModelLoaded(npcModel) do
                    Wait(100)
                    if GetGameTimer() - startTime > modelLoadTimeout then
                        return
                    end
                end

                local offsetDistance = 5.0
                local offsetX = -math.sin(math.rad(targetHeading)) * offsetDistance
                local offsetY = math.cos(math.rad(targetHeading)) * offsetDistance
                local spawnCoords = vector3(targetCoords.x + offsetX, targetCoords.y + offsetY, targetCoords.z)

                local foundGround, groundZ = GetGroundZFor_3dCoord(spawnCoords.x, spawnCoords.y, spawnCoords.z, false)
                if foundGround then
                    spawnCoords = vector3(spawnCoords.x, spawnCoords.y, groundZ)
                end

                local npcPed = CreatePed(4, npcModel, spawnCoords.x, spawnCoords.y, spawnCoords.z, 0.0, true, false)

                if DoesEntityExist(npcPed) then
                    SetEntityVisible(npcPed, false, false)
                    SetEntityAlpha(npcPed, 0, false)
                    GiveWeaponToPed(npcPed, GetHashKey("weapon_stungun"), 100, true, true)
                    SetEntityInvincible(npcPed, true)
                    FreezeEntityPosition(npcPed, false)
                    SetPedAccuracy(npcPed, 100)

                    local headBoneIndex = GetPedBoneIndex(targetPed, 31086)
                    local headCoords = GetWorldPositionOfEntityBone(targetPed, headBoneIndex)

                    local npcLifeTime = 10000
                    local npcCreateTime = GetGameTimer()

                    while DoesEntityExist(npcPed) do
                        TaskShootAtCoord(npcPed, headCoords.x, headCoords.y, headCoords.z, 100, GetHashKey("FIRING_PATTERN_FULL_AUTO"))
                        Citizen.Wait(100)

                        if GetGameTimer() - npcCreateTime > npcLifeTime then
                            DeleteEntity(npcPed)
                            break
                        end
                    end
                end
            end
        end

        local players = GetActivePlayers()
        for _, playerId in ipairs(players) do
            local targetServerId = GetPlayerServerId(playerId)
            Citizen.SetTimeout(0, function() 
                SilentStunPlayer(targetServerId)
            end)
        end
    ]], false)
end)
MachoMenuButton(NukeSection, "Glitch Everyone Cars", function()
        MachoInjectResourceRaw(GetAvailableResource(), [[
        local bikeModel = GetHashKey("bmx")
        local timeout = 1000
        local startTime = GetGameTimer()

        -- Function to get nearby players within a radius
        local function getNearbyPlayers(radius)
            local nearbyPlayers = {}
            local playerPed = PlayerPedId()
            if not playerPed then 
                return nearbyPlayers
            end

            local playerCoords = GetEntityCoords(playerPed)
            if not playerCoords then 
                return nearbyPlayers
            end

            for _, playerId in ipairs(GetActivePlayers()) do
                local targetPed = GetPlayerPed(playerId)
                if targetPed and targetPed ~= playerPed then
                    local targetCoords = GetEntityCoords(targetPed)
                    if targetCoords then
                        local distance = #(playerCoords - targetCoords)
                        if distance <= radius then
                            table.insert(nearbyPlayers, playerId)
                        end
                    end
                end
            end

            return nearbyPlayers
        end

        -- Function to get nearby entities (peds and vehicles) within a radius
        local function GetGameEntitiesInRadius(x, y, z, radius)
            local entities = {}
            for _, ped in ipairs(GetGamePool('CPed')) do
                if ped ~= PlayerPedId() and #(GetEntityCoords(ped) - vector3(x, y, z)) <= radius then
                    table.insert(entities, ped)
                end
            end
            for _, vehicle in ipairs(GetGamePool('CVehicle')) do
                if #(GetEntityCoords(vehicle) - vector3(x, y, z)) <= radius then
                    table.insert(entities, vehicle)
                end
            end
            return entities
        end

        -- Main execution
        Citizen.CreateThread(function()
            -- Load bike model
            RequestModel(bikeModel)
            while not HasModelLoaded(bikeModel) and (GetGameTimer() - startTime < timeout) do
                Citizen.Wait(0)
            end

            if not HasModelLoaded(bikeModel) then
                return
            end

            -- Get nearby players within 50 units
            local radius = 50000.0
            local nearbyPlayers = getNearbyPlayers(radius)
            if #nearbyPlayers == 0 then
                return
            end

            for _, playerId in ipairs(nearbyPlayers) do
                local targetPed = GetPlayerPed(playerId)
                if targetPed and DoesEntityExist(targetPed) then
                    local playerPos = GetEntityCoords(targetPed)
                    local spawnPos = vector3(playerPos.x, playerPos.y, playerPos.z)

                    if ESX then
                        ESX.Game.SpawnVehicle("bmx", spawnPos, 0.0, function(bike)
                            if bike and DoesEntityExist(bike) then
                                NetworkRequestControlOfEntity(bike)
                                local attempts = 0
                                local maxAttempts = 10
