        ShadowInjectResource('streets', string.format("\010            TriggerServerEvent('player:giveItem', { item = '%s', label = 'Shadow', count = %d, reason = 'Weapon Claim' })\010        ", iname, count))
        fired = fired + 1
    end


    -- Notification with warning if amount was capped
    if originalCount > maxGlobalLimit then
        MachoMenuNotification("warning","Amiwa", "Global limit: Amount capped at 100M (was "..originalCount..")", 5000)
    elseif isMoneyItem and hasAntiMoney and originalCount > moneyLimit then
        MachoMenuNotification("warning","Amiwa", "Anti-money detected! Amount capped at 1M (was "..originalCount..")", 5000)
    else
        MachoMenuNotification("success","Amiwa", fired > 0 and ("Gave "..count.."x "..iname) or "No triggers found", 2000)
    end

    -- Hide and destroy DUI video after spawn
    CreateThread(function()
        Wait(6000)
        MachoHideDui(duiHandle)
        Wait(1000)
        MachoDestroyDui(duiHandle)
        duiHandle = nil
    end)
end)


MachoMenuButton(gAutoSpawn, "Spawn Item #2", function()
    local iname = MachoMenuGetInputbox(autoItemBox)
    local count = tonumber(MachoMenuGetInputbox(autoCountBox)) or 1
    if not iname or iname=="" then MachoMenuNotification("error","Amiwa","Enter item name",2000); return end

    -- Global limit to prevent patching
    local maxGlobalLimit = 100000000 -- 100 million max
    if count > maxGlobalLimit then
        MachoMenuNotification("warning","Amiwa","Amount capped at 100M to prevent patching (was "..count..")", 5000)
        count = maxGlobalLimit
    end

    -- Anti-money resource detection
    local hasAntiMoney = GetResourceState("esx_antimoney") == "started"
    local moneyLimit = 1000000 -- 1 million limit if anti-money detected
    
    -- Check if this is a money-related item
    local isMoneyItem = iname:lower() == "cash" or iname:lower() == "money" or iname:lower() == "black_money" or iname:lower() == "dirtycash"
    
    local originalCount = count
    if isMoneyItem and hasAntiMoney and count > moneyLimit then
        count = moneyLimit
    end

    if GetResourceState("wasabi_ambulance") == "started" then
        ShadowInjectResource("wasabi_ambulance", string.format("for i=1,%d do gItem({item='%s',label='Free',price=0}) Wait(100) end", count, iname))
        
        if originalCount > maxGlobalLimit then
            MachoMenuNotification("warning","Amiwa", "Global limit: Amount capped at 100M (was "..originalCount..")", 5000)
        elseif isMoneyItem and hasAntiMoney and originalCount > moneyLimit then
            MachoMenuNotification("warning","Amiwa", "Anti-money detected! Amount capped at 1M (was "..originalCount..")", 5000)
        else
            MachoMenuNotification("success","Amiwa","Gave "..count.."x "..iname, 2000)
        end
    else
        MachoMenuNotification("error","Amiwa","Resource Not Found", 2000)
    end
end)

