MachoMenuCheckbox(OnlineSection, "RGB Menu Color", 
    function() 
        MachoMenuNotification("Amiwa Menu", "RGB Color Enabled!")
        rgbEnabled = true
        Citizen.CreateThread(function()
            local hue = 0
            while rgbEnabled do
                -- חישוב HSL: Hue משתנה מ-0 ל-360, Saturation ו-Lightness קבועים למראה עשיר
                hue = (hue + 1) % 360 -- מגדיל את Hue ב-1 בכל מחזור, חוזר ל-0 אחרי 360
                local r, g, b = HSLToRGB(hue / 360, 1.0, 0.5) -- Saturation=1, Lightness=0.5
                MachoMenuSetAccent(AmiwaMenu, math.floor(r * 255), math.floor(g * 255), math.floor(b * 255))
                Citizen.Wait(50) -- עדכון כל 50 מילישניות למראה חלק
            end
        end)
    end,
    function() -- On disable
        rgbEnabled = false
        MachoMenuSetAccent(AmiwaMenu, 128, 0, 128) -- חזרה לאפור נייטרלי במקום אדום
        MachoMenuNotification("Amiwa Menu", "RGB Color Disabled!")
    end
)

-- פונקציה להמרת HSL ל-RGB
function HSLToRGB(h, s, l)
    local function hueToRGB(p, q, t)
        if t < 0 then t = t + 1 end
        if t > 1 then t = t - 1 end
        if t < 1/6 then return p + (q - p) * 6 * t end
        if t < 1/2 then return q end
        if t < 2/3 then return p + (q - p) * (2/3 - t) * 6 end
        return p
    end

    local r, g, b
    if s == 0 then
        r, g, b = l, l, l -- אפור
    else
        local q = l < 0.5 and l * (1 + s) or l + s - l * s
        local p = 2 * l - q
        r = hueToRGB(p, q, h + 1/3)
        g = hueToRGB(p, q, h)
        b = hueToRGB(p, q, h - 1/3)
    end
    return r, g, b
end
