-- Keybind data: mapping virtual-key codes to human-readable names
local keyMap = {
    ["+"] = 0xBB,
    ["-"] = 0xBD,
    ["="] = 0xBB,
    ["backspace"] = 0x08,
    ["tab"] = 0x09,
    ["enter"] = 0x0D,
    ["shift"] = 0x10,
    ["ctrl"] = 0x11,
    ["alt"] = 0x12,
    ["caps"] = 0x14,
    ["esc"] = 0x1B,
    ["space"] = 0x20,
    ["pageup"] = 0x21,
    ["pagedown"] = 0x22,
    ["end"] = 0x23,
    ["home"] = 0x24,
    ["left"] = 0x25,
    ["up"] = 0x26,
    ["right"] = 0x27,
    ["down"] = 0x28,
    ["insert"] = 0x2D,
    ["delete"] = 0x2E,
    ["f1"] = 0x70, ["f2"] = 0x71, ["f3"] = 0x72, ["f4"] = 0x73,
    ["f5"] = 0x74, ["f6"] = 0x75, ["f7"] = 0x76, ["f8"] = 0x77,
    ["f9"] = 0x78, ["f10"] = 0x79, ["f11"] = 0x7A, ["f12"] = 0x7B,
    ["a"] = 0x41, ["b"] = 0x42, ["c"] = 0x43, ["d"] = 0x44, ["e"] = 0x45,
    ["f"] = 0x46, ["g"] = 0x47, ["h"] = 0x48, ["i"] = 0x49, ["j"] = 0x4A,
    ["k"] = 0x4B, ["l"] = 0x4C, ["m"] = 0x4D, ["n"] = 0x4E, ["o"] = 0x4F,
    ["p"] = 0x50, ["q"] = 0x51, ["r"] = 0x52, ["s"] = 0x53, ["t"] = 0x54,
    ["u"] = 0x55, ["v"] = 0x56, ["w"] = 0x57, ["x"] = 0x58, ["y"] = 0x59,
    ["z"] = 0x5A,
    ["0"] = 0x30, ["1"] = 0x31, ["2"] = 0x32, ["3"] = 0x33, ["4"] = 0x34,
    ["5"] = 0x35, ["6"] = 0x36, ["7"] = 0x37, ["8"] = 0x38, ["9"] = 0x39
}

MachoMenuSetKeybind(AmiwaMenu, 0x22)

local Keybind_Input = MachoMenuInputbox(OnlineSection, "Keybind", "EX: + / insert / f8")

MachoMenuButton(OnlineSection, "Set Menu Keybind", function()
    local Input_Event = MachoMenuGetInputbox(Keybind_Input)
    local keycode = nil
    if Input_Event ~= nil and Input_Event ~= '' then
        local lowered = string.lower(tostring(Input_Event))
        lowered = lowered:gsub("%s+", "")
        keycode = keyMap[lowered]
        if not keycode then
            local num = tonumber(Input_Event)
            if num ~= nil then
                keycode = num
            end
        end
    end

    if not keycode then 
        MachoMenuNotification("Amiwa Menu", "Invalid key input. Using default: +")
        keycode = 0xBB 
    end
    
    MachoMenuSetKeybind(AmiwaMenu, keycode)
    MachoMenuNotification("Amiwa Menu", "Menu keybind updated successfully!")
end)